def _anyio_channels(node, tokens=_ANYIO_INTROSPECTION):
    """The tokens of `tokens` (_ANYIO_INTROSPECTION's, else _ANYIO_DIRECT_WHOLESALE's) the node `node` names, read one
    way in the conftest's text and in the whole text of a module of the repository it imports directly (THE ANYIO
    RULE's runtime-introspection refusal, and its wholesale refusal of such a module): a Name's
    id, an Attribute's attr, an arg's, a keyword's, a def's or a class's name, an alias's name and asname, an
    ImportFrom's module and the names of a global or nonlocal statement, each whole and by its dotted parts, and the
    dotted-or-coloned parts of a str or bytes literal (bytes read as latin-1), the forms the rule reads names in."""
    if isinstance(node, ast.Constant) and isinstance(node.value, (str, bytes)):
        text = node.value.decode("latin-1") if isinstance(node.value, bytes) else node.value
        return frozenset(re.split(r"[.:]", text)).intersection(tokens)
    if isinstance(node, ast.Name):
        spelled = [node.id]
    elif isinstance(node, ast.Attribute):
        spelled = [node.attr]
    elif isinstance(node, ast.arg):
        spelled = [node.arg]
    elif isinstance(node, ast.alias):
        spelled = [node.name, node.asname or ""]
    elif isinstance(node, ast.ImportFrom):
        spelled = [node.module or ""]
    elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        spelled = [node.name]
    elif isinstance(node, ast.keyword):
        spelled = [node.arg or ""]
    elif isinstance(node, (ast.Global, ast.Nonlocal)):
        spelled = list(node.names)
    else:
        return frozenset()
    return frozenset(p for s in spelled for p in (s, *s.split("."))).intersection(tokens)


def _anyio_identifier_names(node):
    """Every identifier and attribute name the node `node` names, by THE ANYIO RULE's own reading (_anyio_channels'
    forms, but a str or bytes literal names nothing here): a Name's id, an Attribute's attr, an arg's, a keyword's, a
    def's or a class's name, an alias's name and asname, an ImportFrom's module and the names of a global or nonlocal
    statement, each whole and by its dotted parts. This is the alphabet of THE POSITIVE ALLOWLIST (_ANYIO_DIRECT_ALLOWED)
    -- the identifiers and attribute names a module of the repository the conftest imports directly may name -- read the
    same way over that module's text and over tests/__init__.py, so the derived set and a direct import's names are
    compared on the same footing (the reviewer's ruling of 2026-09-29 15:08Z on round 2 of fork PR #894)."""
    if isinstance(node, ast.Name):
        spelled = [node.id]
    elif isinstance(node, ast.Attribute):
        spelled = [node.attr]
    elif isinstance(node, ast.arg):
        spelled = [node.arg]
    elif isinstance(node, ast.alias):
        spelled = [node.name, node.asname or ""]
    elif isinstance(node, ast.ImportFrom):
        spelled = [node.module or ""]
    elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        spelled = [node.name]
    elif isinstance(node, ast.keyword):
        spelled = [node.arg or ""]
    elif isinstance(node, (ast.Global, ast.Nonlocal)):
        spelled = list(node.names)
    else:
        return frozenset()
    return frozenset(p for s in spelled for p in (s, *s.split(".")) if p)


def _anyio_direct_allowed_names(tree):
    """The identifiers and attribute names `tree` (tests/__init__.py's) names, by _anyio_identifier_names read over its
    whole text: THE POSITIVE ALLOWLIST derived. The pin asserts this equals _ANYIO_DIRECT_ALLOWED, so a name added to
    tests/__init__.py reds loudly and names itself (the set is reviewed and re-committed)."""
    out = set()
    for n in ast.walk(tree):
        out |= _anyio_identifier_names(n)
    return frozenset(out)


def _anyio_module_file(dotted, dirs):
    """The file of the module `dotted` of the repository among the directories `dirs` (_import_roots'): a package's
    __init__.py, or a module's .py; "" for a directory with no __init__.py (a namespace package, which binds nothing);
    None where none of them holds it. The first of them that holds its first part decides, as _shadowed reads them."""
    parts = dotted.split(".")
    for d in dirs:
        if os.path.isdir(os.path.join(d, parts[0])) or os.path.isfile(os.path.join(d, parts[0] + ".py")):
            base = os.path.join(d, *parts)
            if os.path.isfile(os.path.join(base, "__init__.py")):
                return os.path.join(base, "__init__.py")
            if os.path.isfile(base + ".py"):
                return base + ".py"
            return "" if os.path.isdir(base) else None
    return None


def _anyio_absolute(stmt, package):
    """The dotted module the from import `stmt` names, a relative one resolved against `package` (the text's package,
    from _import_roots); None past it."""
    if not stmt.level:
        return stmt.module
    parts = package.split(".") if package else []
    if stmt.level > len(parts):
        return None
    return ".".join(parts[:len(parts) - stmt.level + 1] + ([stmt.module] if stmt.module else []))


def _anyio_namespace_write(x, parent):
    """Why the read `x`, a name globals, vars or locals that no declaration binds, may write the namespace it returns,
    else None (`parent` maps each node of its tree to the node holding it): only a call whose result is read by a
    subscript in a load, by a read-only method called (get, keys, values, items, copy and the like) or by `in` is not."""
    p = parent.get(x)
    if not (isinstance(p, ast.Call) and p.func is x):
        return "%s read other than as a call's callee" % x.id
    use = parent.get(p)
    if isinstance(use, ast.Subscript) and use.value is p:
        return None if isinstance(use.ctx, ast.Load) else "a write to an item of %s()" % x.id
    if isinstance(use, ast.Attribute) and use.value is p:
        call = parent.get(use)
        if (use.attr in ("get", "keys", "values", "items", "copy", "__contains__", "__getitem__", "__len__", "__iter__")
                and isinstance(call, ast.Call) and call.func is use):
            return None
        return "%s().%s, which may write it" % (x.id, use.attr)
    if isinstance(use, ast.Compare) and any(c is p for c in use.comparators) and all(
            isinstance(o, (ast.In, ast.NotIn)) for o in use.ops):
        return None
    return "%s() held whole (bound to a name, handed to a call, iterated or returned)" % x.id


def _anyio_addini_refusal(attr, parent):
    """Why THE ANYIO RULE refuses the ini registration `attr` (an attribute named addini, _ANYIO_INI_REGISTRARS;
    `parent` maps each node of its tree to the node holding it), else None: read other than as the callee of a call;
    a call handed keywords through **, or passing aliases=, either of which can register an alias that getini resolves
    to the setting registered; a call whose name, its first argument or its name=, is not a str literal (a name, a
    starred argument, none); and a call whose name is a key getini is refused to read by name (addopts, markers:
    _ANYIO_KEYED['getini']), registered again. The aliases are keyword-only in pytest 9's Parser.addini, so a starred
    argument after a literal name cannot pass them. The reviewer's ruling of 2026-09-30 12:50Z on round 2 of fork PR
    #894, item 1: a conftest's own parser.addini('addopts', ..., aliases=['cmdini']) made getini('cmdini') read addopts
    while the rule proved the literal key 'cmdini'."""
    p = parent.get(attr)
    if not (isinstance(p, ast.Call) and p.func is attr):
        return ("the ini registration %s read other than as a call, so the name and the aliases each call of it "
                "registers are not in the text" % attr.attr)
    if any(k.arg is None for k in p.keywords):
        return ("the ini registration %s handed keywords through **, which can pass aliases=, an alias getini resolves "
                "to the setting registered" % attr.attr)
    if any(k.arg == "aliases" for k in p.keywords):
        return ("the ini registration %s passing aliases=, which getini resolves to the setting registered (pytest 9: "
                "parser.addini('addopts', ..., aliases=['cmdini']) makes getini('cmdini') read addopts), so a literal "
                "key of getini may read a setting the rule refuses it to read by name" % attr.attr)
    name = p.args[0] if p.args else next((k.value for k in p.keywords if k.arg == "name"), None)
    if not (isinstance(name, ast.Constant) and isinstance(name.value, str)):
        return ("the ini registration %s whose name is not a str literal, so the rule does not read which setting it "
                "registers" % attr.attr)
    if name.value in _ANYIO_KEYED["getini"]:
        return ("the ini registration %s of %r, a setting getini is refused to read by name (the ini's addopts carries "
                "options, its markers the markers each plugin registers), registered again" % (attr.attr, name.value))
    return None


def _anyio_resolution(bindings, name_node):
    """(declarations, scope, unbound) for the Name read `name_node`, by THE ANYIO RULE's own resolution, the one every
    site of the rule resolves a name through (_anyio_option_reads' declared, unbound and outside_a_function; the
    direct-import check's resolved, loose and outer, and so is_sys, targets and dundered; and _anyio_imported_module's
    reading of a name it matched): ast_bindings' scope rule (`bindings`.scope_of(name_node).resolve), except for a read
    in a CLASS BODY of a name that class binds. Python reads a name in a class body by LOAD_NAME, the class's namespace,
    then the module's, then the builtins, so where the class has not bound the name at that point (a read ahead of the
    binding, after a del, or with the binding in a branch not taken) the read takes the module's binding, or the builtin
    where the module binds none, and never an enclosing def's (for a class in a def, a name the class binds is read by
    LOAD_NAME too); ast_bindings.Scope.resolve returns the class's declarations alone. Here such a read resolves to the
    class's declarations PLUS the module scope's, and, where the module binds none, to no binding as well (`unbound`),
    so the checks for a name no declaration binds (the builtins vars, globals and locals; sys where nothing binds it)
    apply to it (the reviewer's ruling of 2026-09-30 12:50Z on round 2 of fork PR #894, item 2, built here and not in
    ast_bindings.Scope, which other censuses share). A read that may take no binding is also one whose declarations
    stand in the module's scope, or in such a class body and the module's, and whose name is a BUILTIN'S (one the
    builtins module of the interpreter reading the text binds), or whose text holds a STAR IMPORT anywhere
    (_anyio_star_imported): Python reads the module's namespace and then the builtins, so where the module's binding
    has not run (a del, a branch not taken, a read ahead of it) the read takes the builtin, as a read in a class body
    does, and a star import binds names in the module's namespace that no declaration records, so the read may take
    the star import's binding and no declaration's, the star import running after the declarations or they not having
    run (the verification of the hundred and eighteenth round-2 commit of fork PR #894 found vars bound and deleted, or
    bound in a branch not taken, at the module's level admitted while the read of vars(sys) took the builtin, and the
    same for globals, and the hundred and nineteenth carries ruled item 2's "no binding" to them; the re-verification
    of the hundred and nineteenth found from _ih import * beside the module's own lineage = 'zz', ahead of the read,
    before the star import, in a branch not taken, or beside a class body's own later lineage = 'zz' as well, and then
    'an' + lineage + 'yio' admitted while Python bound anyio, the same for PYTEST_ADDOPTS, and sys.path read where the
    star import binds sys beside sys = None, each since the star import's binding was read only where no declaration
    binds the name, and the hundred and twentieth reads it wherever the module's declarations do). A def's, a lambda's
    or a comprehension's own binding is left out: a read there takes the local or raises, and never reads the builtin
    or a star import's binding. A fold reads such a read as the empty string, open, beside the values its declarations
    give (through, in _anyio_option_reads), as it reads a name no declaration binds: a star import may bind the name
    to a str the rule does not read, so from _ih import * and then 'an' + lineage + 'yio' names anyio whether the text
    declares lineage in the module's scope or a class body's or nowhere. `scope` is the scope resolve names (the
    class's, for such a read; None where no scope binds the name); `unbound` is whether the read may take no binding:
    no declaration binds it, it is such a class-body read and the module binds none, or its declarations stand in the
    module's scope (or such a class body's) and it names a builtin or its text holds a star import. An AssertionError
    from scope_of (a node of another tree) propagates."""
    decls, where = bindings.scope_of(name_node).resolve(name_node.id)
    builtin = name_node.id in vars(builtins)
    star = _anyio_star_imported(bindings)
    if where is None or where.kind != "class":
        return decls, where, not decls or (where is not None and where.kind == "module" and (builtin or star))
    more = list(where.module().names.get(name_node.id, ()))
    return decls + more, where, not more or builtin or star


_ANYIO_STAR_IMPORTS = weakref.WeakKeyDictionary()
#   {ast_bindings.Bindings: whether the text it was built over holds a star import}, filled by _anyio_star_imported on
#   its first read of each text, so _anyio_resolution, which the rule calls for every name read it resolves, walks a
#   text once; weak, so an entry goes with its bindings


def _anyio_star_imported(bindings):
    """Whether the text `bindings` was built over holds a STAR IMPORT (from m import *) anywhere. A star import binds, in
    the module's namespace, names no declaration of the text records (ast_bindings records none for it), whatever the
    text declares for them there; Python compiles one at the module's level alone, so reading the whole text errs only
    toward reading more. Read once per text (_ANYIO_STAR_IMPORTS). _anyio_resolution reads a read whose declarations
    stand in the module's scope (or in a class body's and the module's) as one that may take no binding where this
    holds (the re-verification of the hundred and nineteenth round-2 commit of fork PR #894, carried out by the hundred
    and twentieth)."""
    got = _ANYIO_STAR_IMPORTS.get(bindings)
    if got is None:
        got = any(isinstance(s, ast.ImportFrom) and any(a.name == "*" for a in s.names) for s in ast.walk(bindings.tree))
        _ANYIO_STAR_IMPORTS[bindings] = got
    return got


def _anyio_fold_sites(n, declared):
    """The expressions THE ANYIO RULE folds at the node `n` of its walk, for the first clause (a value naming anyio,
    PYTEST_ADDOPTS or mainargv): `n` itself where it is a literal, a +, % or * operation or an f-string; and, where `n`
    is an augmented assignment to a name (K += 'yio', K %= 'yio'), the composed value its declaration holds (`K op
    value`, the value ast_bindings records for an augmented assignment, which is no node of the tree, so the walk never
    meets it as an operation); none for any other node. `declared` is the rule's resolution of a Name read to its
    declarations (None where none binds it). Until the hundred and nineteenth round-2 commit of fork PR #894 the walk
    folded the first three alone, so K = 'an' then K += 'yio' then K in sys.modules, and K = 'PYTEST_' then K +=
    'ADDOPTS' then os.environ.get(K), were each admitted while Python bound anyio and PYTEST_ADDOPTS: the composed value
    was folded only where a later operation or f-string read K (the verification of the hundred and eighteenth found
    the form, which the first clause names, admitted since the ninety-second)."""
    if isinstance(n, (ast.Constant, ast.BinOp, ast.JoinedStr)):
        return [n]
    if isinstance(n, ast.AugAssign) and isinstance(n.target, ast.Name):
        return [d.value for d in (declared(n.target) or ()) if d.node is n and d.value is not None]
    return []


_ANYIO_BUILTIN_DEFEATER_CALLS = {
    (None, "setattr"): "setattr", (None, "delattr"): "delattr", (None, "compile"): "compile",
    ("builtins", "setattr"): "setattr", ("builtins", "delattr"): "delattr", ("builtins", "compile"): "compile",
    ("builtins", "__setattr__"): "setattr", ("builtins", "__delattr__"): "delattr",
    ("object", "__setattr__"): "setattr", ("object", "__delattr__"): "delattr"}
#   THE BUILTIN DEFEATERS of a literal key (_anyio_builtin_defeaters), {(the name the callee is read as an attribute of,
#   None for a bare name; the callee's name): the builtin the call reaches}: ten clauses, one per spelling. Each has its
#   own plant in test_the_conftests_builtin_setattr_delattr_and_compile_defeat_a_literal_key, which shows the plant
#   refused and then admitted with that one entry removed, and holds the plants' clauses equal to these keys (the
#   reviewer's ruling of 2026-09-29 15:08Z on round 2 of fork PR #894, "a mutant per clause", and its ruling of
#   2026-09-30 12:50Z, item 4, which found five of the ten with no plant: builtins.delattr, builtins.compile,
#   builtins.__setattr__, builtins.__delattr__ and object.__delattr__)


def _anyio_builtin_defeaters(tree, proven):
    """Why the conftest's own text names a builtin that defeats a literal key: a setattr, delattr or object.__setattr__
    call -- a BARE NAME (setattr, delattr), through builtins (builtins.setattr, builtins.delattr, builtins.__setattr__,
    builtins.__delattr__) or object.__setattr__/object.__delattr__ -- whose target name (its second argument) THE PROOF
    does not prove, since such a call can rewrite the hook's code object, and with it the literal its keyed read is
    handed (setattr), or remove the attribute a read by a literal key resolves, so it resolves another, a base class's
    (delattr); and a compile() call (a bare name, or builtins.compile), which builds code the rule does not parse. The
    spellings are the ten keys of _ANYIO_BUILTIN_DEFEATER_CALLS, read from that table at each call. "" for none (the
    reviewer's ruling of 2026-09-29 15:08Z on round 2 of fork PR #894, its second medium; since the hundred and fourteenth round-2
    commit a literal key is the one key THE PROOF proves, so these defeat a literal key alone, the reviewer's ruling of
    2026-09-30 01:04Z keeping them for a literal key whose hook's code is rewritten). The builtin is told from an
    attribute call of the same name: re.compile and monkeypatch.setattr are attributes of a name other than builtins or
    object, not the builtin, and are NOT defeaters (the live conftest names both, at re.compile and
    monkeypatch.setattr). A call whose target name IS proven (setattr(o, 'attr', v) by a literal) names one fixed
    attribute, not the key, and is no defeater."""
    for n in ast.walk(tree):
        if not isinstance(n, ast.Call):
            continue
        f = n.func
        spelled = ((None, f.id) if isinstance(f, ast.Name)
                   else (f.value.id, f.attr) if isinstance(f, ast.Attribute) and isinstance(f.value, ast.Name) else None)
        kind = _ANYIO_BUILTIN_DEFEATER_CALLS.get(spelled)   # "setattr" | "delattr" | "compile", called as the builtin
        if kind is None:
            continue
        if kind == "compile":
            return ("a builtin compile() call (a bare name, or through builtins), which builds code the rule does not parse, "
                    "so a literal key beside it is not safe")
        target = n.args[1] if len(n.args) >= 2 else None
        if target is None or proven(target)[0] is None:
            return ("a builtin %s() call whose target name THE PROOF does not prove, which can rewrite the hook's code "
                    "object, so a literal key beside it is not safe" % kind)
    return ""


