def _loads_kernel(stmt):
    """True for a module-level statement that load_source()s the kernel (its module name starts with romp_kernel)."""
    return any(isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == "load_source" and n.args
               and isinstance(n.args[0], ast.Constant) and str(n.args[0].value).startswith("romp_kernel")
               for n in ast.walk(stmt))


def _attaches_or_detaches(cls):
    """True for a class whose tests reach the tunnel spawn or a detach: a detach_remote call, the /tunnels routes, or an
    attach_remote call outside an assertRaises (an attach expected to raise is refused by host validation before the
    tunnel or the bus is touched)."""
    expected = set()
    for n in ast.walk(cls):
        if isinstance(n, ast.With) and any(isinstance(i.context_expr, ast.Call) and isinstance(i.context_expr.func, ast.Attribute)
                                            and i.context_expr.func.attr == "assertRaises" for i in n.items):
            expected.update(id(c) for b in n.body for c in ast.walk(b))
    for n in ast.walk(cls):
        if isinstance(n, ast.Attribute) and n.attr == "detach_remote":
            return True
        if isinstance(n, ast.Attribute) and n.attr == "attach_remote" and id(n) not in expected:
            return True
        if isinstance(n, ast.Constant) and isinstance(n.value, str) and n.value.startswith("/tunnels"):
            return True
    return False


def _method_chain(cls, name, classes, _seen=frozenset()):
    """The FunctionDefs that run when `name` is called on `cls`: its own, then a base's (through the bases defined in
    the same module) when the own one delegates with super().<name>() or there is no own one. Empty when nothing runs.
    Its own are every def of that name its body's import-time blocks bind (_import_time_defs; one under a class-body
    `if` included, round 2 of fork PR #894); `classes` maps a name to a class or to a list of every class bound to it,
    each read; a base defined in another module is not followed (named above _Module); `_seen` cuts a class that names
    itself, through a redefinition, as its own base."""
    owns = _import_time_defs(cls.body)[0].get(name, [])
    chain = list(owns)
    delegates = not owns or any(
        isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr == name
        and isinstance(n.func.value, ast.Call) and isinstance(n.func.value.func, ast.Name) and n.func.value.func.id == "super"
        for own in owns for n in ast.walk(own))
    if delegates:
        for b in cls.bases:
            if isinstance(b, ast.Name):
                for base in _as_list(classes.get(b.id)):
                    if id(base) not in _seen and base is not cls:
                        chain += _method_chain(base, name, classes, _seen | {id(cls)})
    return chain


def _parser_singletons():
    """{"Load": node, "Store": node, "Del": node}: the expression-context nodes the PARSER hands out, one object each for
    the whole process (`ast.Load()` constructs a new one, so the pins read them from a parse), asserted shared between two
    parses, since the two pins that rest on the sharing would hold vacuously without it."""
    one, two = ast.parse("a = b\ndel c").body, ast.parse("x = y\ndel z").body
    pairs = {"Load": (one[0].value.ctx, two[0].value.ctx), "Store": (one[0].targets[0].ctx, two[0].targets[0].ctx),
             "Del": (one[1].targets[0].ctx, two[1].targets[0].ctx)}
    for kind, (p, q) in pairs.items():
        if p is not q:
            raise AssertionError("two parses gave two %s nodes; the parser hands out one for the process, and the pins over "
                                 "the shared singletons rest on that" % kind)
    return {kind: p for kind, (p, _q) in pairs.items()}


def _restore_dict(obj, saved):
    """`obj.__dict__` put back to `saved`: the cleanup for a plant on a process-wide singleton every test shares."""
    obj.__dict__.clear()
    obj.__dict__.update(saved)


class _Link:
    """One link of the deep synthetic chain the plant hangs on the parser's Load singleton: a deepcopy that follows the tag
    walks the chain and recurses once per link."""

    def __init__(self, tail):
        self.tail = tail


_COLLECTOR_READS = ("get_freeze_count", "get_objects")
#   the two attributes of gc this module may touch outside the tests of _COLLECTOR_STATE_TESTS, each a read that changes
#   no collector state: the freeze-count pin's (setUpModule, tearDownModule), and the list of tracked objects that
#   _held_alive and _born read (before and after the loop of a census build that drops a tree, THE DROP BY LIVE OBJECTS;
#   at the start and the end of the tree's read that counts; setUpModule's start list and the module end's count)

_COLLECTOR_STATE_TESTS = {
    "test_the_read_drops_no_cycle_so_each_module_is_freed_by_reference_counting":
        ("isenabled", "enable", "disable", "collect", "get_debug", "set_debug", "garbage", "DEBUG_SAVEALL"),
    "test_a_scan_of_a_planted_source_leaves_no_cycle_holding_its_tree": ("isenabled", "enable", "disable"),
}
#   fork PR #850's two tests of HermeticKernelPostal that change the collector's state, which the merged module keeps
#   (the reviewer's ruling of round 2 on fork PR #894, group C: every source-reading pin of either PR re-aimed and green
#   on the merged module), each with the attributes of gc it may touch: both turn automatic collection off, putting the
#   collector's state back as they found it by a cleanup registered before the change; the cycle test also runs
#   gc.collect() twice, the second under DEBUG_SAVEALL, whose debug flags a cleanup registered before the change puts
#   back


def _collector_touches(tree):
    """(line, spelling) for every place in `tree` that reaches the collector's state or parse_cache's memo: an attribute of
    a name bound to the gc module (`import gc`, `import gc as g`) other than _COLLECTOR_READS, any name imported from gc
    (`from gc import freeze`), and the attribute `derived` of a name bound to tests/parse_cache.py (`PC.derived`,
    `parse_cache.derived`, or under any alias an import gives it). An attribute is read wherever it stands, called or not,
    so `f = gc.freeze` counts as `gc.freeze`. What it does not read: a string that names one (getattr(gc, "freeze"),
    importlib.import_module("gc"), exec or eval of a text), a module reached through another (sys.modules["gc"]), and a
    helper module this one imports that touches them (tests/parse_cache.py itself calls gc.freeze inside derived(), which
    this module does not call)."""
    gc_names, pc_names, out = set(), set(), []
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names:
                if a.name == "gc":
                    gc_names.add(a.asname or "gc")
                elif a.name.split(".")[-1] == "parse_cache":
                    pc_names.add(a.asname or a.name)
        elif isinstance(n, ast.ImportFrom):
            if n.module == "gc":
                out += [(n.lineno, "from gc import %s" % a.name) for a in n.names]
            for a in n.names:
                if a.name == "parse_cache":
                    pc_names.add(a.asname or a.name)
    for n in ast.walk(tree):
        if isinstance(n, ast.Attribute):
            base = ".".join(_dotted(n.value) or [])
            if base in gc_names and n.attr not in _COLLECTOR_READS:
                out.append((n.lineno, "%s.%s" % (base, n.attr)))
            elif base in pc_names and n.attr == "derived":
                out.append((n.lineno, "%s.derived" % base))
    return sorted(out)


_FREEZE_AT_START = []
#   gc.get_freeze_count() as setUpModule read it, for tearDownModule's second read (THE FREEZE-COUNT PIN)


def setUpModule():
    """The start of this module's run: the built-once and parse-once counts are zeroed (a worker that sets the module up
    again parses and builds again, after tearDownModule released what the run held), and gc.get_freeze_count() is read
    for THE FREEZE-COUNT PIN in tearDownModule (the reviewer's ruling of 2026-09-24 on round 2 of fork PR #894, clause 3).
    Read here and not at import: pytest imports every module at collection, before any test runs, and another module's
    freeze may run in between. The execution proof's copy counts (_PROOF_RUN) are zeroed too, for THE ONE-COPY PIN.
    Last, the list _still_held reads against (_AT_START, fork PR #850's): _held_alive() at the module's start, held until
    the module ends, so an object alive at the start is never counted as made in the module's run, whatever becomes of
    it, and no id is reused. No collection runs."""
    _CENSUS_BUILDS.clear()
    _OWN_PARSES.clear()
    _PROOF_RUN.clear()
    _FREEZE_AT_START[:] = [gc.get_freeze_count()]
    _AT_START[:] = [_held_alive()]


def tearDownModule():
    """The end of this module's run, and its pins on what the module leaves behind: fork PR #894's (the reviewer's rulings of
    2026-09-24 on round 2 of fork PR #894: clause 3 of the first, fork PR #909's pin (2), which the second applies, and
    the third's parse-once rule), then fork PR #850's checks (_module_end_checks), read after THE RELEASE so that a
    census tree nothing else keeps is dead when its count of what the module's run left alive reads, and the nodes of
    one something else keeps are counted there; the faults of both halves are joined in one error.
    THE RELEASE: _HELD, the one owner, is emptied, which frees the _Census by reference count, no collection running
    here, and with it whatever of the census's own trees, the resolver's records and the derivations nothing else
    keeps. THE RELEASE PIN: a weak reference to the _Census, taken just before the release, is dead just after it. Red
    under the release removed (the trees would stay tracked for the rest of the process, the cost the shape exists to
    avoid), under a module-scope cache that keeps the _Census, and under a value inside it that refers back to it, a
    cycle only a collection frees.
    It does not see an inner container kept by another name or a cycle among the inner containers that does not pass
    through the _Census (module_level_env_census's docstring gives that half as a measurement), and it is not read
    through gc.get_objects(), which does not list frozen objects. A module run that read no census holds nothing and has
    nothing to release. THE PARSE-ONCE PIN OVER THE RUN: no file was parsed twice by the census in the module's run
    (_OWN_PARSES), whichever tests read it and in whatever order, the per-test pins reading only the files of their own
    census at their own moment; red under a census loop that keeps no tree (a file it dropped is parsed again when the
    resolver reads it), the failure _resolver_targets exists to prevent. THE FREEZE-COUNT PIN: gc.get_freeze_count() is
    read again after the release and is not above what setUpModule read, so the module froze nothing (a build behind
    parse_cache.derived freezes every object tracked when it returns, and every later perf-snapshot read in the process
    walks them). The count is live and falls when a frozen object dies, so an object frozen before this module can lower
    it in between, while only a freeze in this module's run raises it; hence not above, rather than equal. Two reads
    only: each walks the frozen objects. THE ONE-COPY PIN (the reviewer's ruling of 2026-09-25 01:54Z on round 2 of
    fork PR #894, (6): one copy per module run, shared by all cases): the one copy of the checkout (_PROOF_COPY) is
    removed, and the run made exactly one copy if it read one at all and none if it read none (_PROOF_RUN, by
    equality); red under a copy made per proof or per case, when the run's worker ran two `real` proofs (the copy's
    own test holds a proof to the copy it read, on every worker), and under the removal dropped. A red here is
    pytest's error at the teardown of the module's last test, naming each pin that failed, fork PR #850's checks among
    them."""
    scratch = _PROOF_COPY.pop() if _PROOF_COPY else None
    if scratch is not None:
        shutil.rmtree(scratch, True)
    made, reads, cases = _PROOF_RUN["copies"], _PROOF_RUN["reads"], _PROOF_RUN["real cases"]
    held = _HELD[0] if _HELD else None
    ref = weakref.ref(held) if held is not None else None
    del held
    _HELD.clear()
    problems = []
    if ref is not None and ref() is not None:
        problems.append("the release pin: the census's _Census is alive after tearDownModule emptied _HELD, its one owner: "
                        "something else keeps it (a module-scope cache, a test's own reference) or a value inside it refers "
                        "back to it, a cycle only a collection frees, and this module runs none; its trees stay tracked for "
                        "the rest of the process")
    twice = sorted(os.path.relpath(real, HERE) for real, n in _OWN_PARSES.items() if n > 1)
    if twice:
        problems.append("the parse-once pin over the module's run: %s parsed more than once by the census (_own_tree): a file "
                        "the census loop dropped after its walk was read again, by the resolver or another census; "
                        "_resolver_targets decides which trees the loop keeps" % ", ".join(twice))
    after = gc.get_freeze_count()
    before = _FREEZE_AT_START.pop() if _FREEZE_AT_START else None
    if before is not None and after > before:
        problems.append("the freeze-count pin: tests/test_hermetic_kernel_postal.py froze objects in its run: "
                        "gc.get_freeze_count() read %d at setUpModule and %d at tearDownModule, after the release. The module "
                        "freezes nothing (the reviewer's ruling of 2026-09-24 on round 2 of fork PR #894): its "
                        "census parses its own trees and never derives through parse_cache.derived, which calls gc.freeze() "
                        "after a build" % (before, after))
    if (made, _PROOF_COPY) != (min(reads, 1), []) or (scratch is not None and os.path.lexists(scratch)):
        problems.append("the one-copy pin: the module's run made %d copies of the checkout over %d reads and %d real cases "
                        "of the execution proof, where one copy serves every read and case of the run and none is made for "
                        "none, and the copy is removed at the module's teardown (left: %s)"
                        % (made, reads, cases, [p for p in [scratch] + _PROOF_COPY if p and os.path.lexists(p)]))
    try:
        _module_end_checks()
    except AssertionError as e:
        problems.append(str(e))
    if problems:
        raise AssertionError("; ".join(problems))


class HermeticKernelPostal(unittest.TestCase):
    def test_kernel_env_gives_every_lab_kernel_its_own_never_started_bus(self):
        self.addCleanup(lab_ports.release, "/tmp/lab")   # the stand-in lab's postal port, held until the test ends
        env = _lab.kernel_env("/tmp/lab", "/tmp/lab/claude", "/tmp/lab/dist", 1, "tok")
        self.assertEqual(env.get("ROMP_POSTAL_CLIENT_ONLY"), "1", "the kernel's ensure starts no bus")
        self.assertEqual(env.get("ROMP_POSTAL_PEERS"), "0")
        port = int(env.get("ROMP_POSTAL_PORT") or 0)
        self.assertTrue(port and port != 25302, "an ephemeral port, never the machine's fixed bus port: %r" % env.get("ROMP_POSTAL_PORT"))
        self.assertEqual(env.get("ROMP_POSTAL_HERMETIC"), "1", "…marked as the run's own, so the bus honours it under a test (2026-09-11)")

    def test_the_runner_pops_an_inherited_bus_port_and_marks_the_runs_own(self):
        src = _source(os.path.join(HERE, "conftest.py"))
        self.assertIn('os.environ.pop("ROMP_POSTAL_PORT", None)', src, "a machine's named bus port never reaches a lab or an in-process kernel")
        self.assertIn('os.environ["ROMP_POSTAL_HERMETIC"] = "1"', src)
        self.assertIn('os.environ["ROMP_POSTAL_CLIENT_ONLY"] = "1"', src, "no in-process kernel of the run owns a bus: its ensure and revive start none (2026-09-18)")
        floor = src.index('os.environ.pop("ROMP_STATE_DIR", None)')
        self.assertLess(floor, src.index('os.environ.pop("ROMP_POSTAL_PORT", None)'), "…beside the state floor, at import, before any test module loads")
        self.assertLess(src.index('os.environ.pop("ROMP_POSTAL_PORT", None)') - floor, 600, "…right beside it")

    def test_every_test_that_starts_a_kernel_process_carries_the_trio(self):
        """Keyed on the spawn's argv read from each module's ast, every name resolved to its binding (_SpawnScan over
        ast_bindings), and on the trio's presence in the module's text (_hermetic); a module the scan can read neither
        way is loud here (UnreadableSpawn), never passed over. The offender is named with the file, the line and the
        argv. Read from the roads table over the tree (_roads_table), the table of the module run's one read, which the
        guard test, the comparison case and the --roads arm read too."""
        offenders = _kernel_spawn_offenders(HERE, skip=TREE_SKIP)
        self.assertEqual(offenders, [], "these tests start a kernel process without the postal trio (use kernel_env, or set "
                                        "ROMP_POSTAL_PORT to a free port, ROMP_POSTAL_PEERS=0 and ROMP_POSTAL_CLIENT_ONLY=1), "
                                        "(file, line, argv): %r" % offenders)

    def test_the_guard_itself_sees_the_spawn_sites(self):
        """The scan must read the spawn idioms the labs use, else the trio rule above would pass vacuously; and it must
        refuse the shapes the regex census read wrongly (2026-09-21), else the rule reds on a module that starts no
        kernel. The tree: the roads table over every module the trio test reads (spawn_roads, the one read the
        trio test uses as well; the `--roads` arm prints it) holds the lab modules, test_federation_missing_served.py
        and test_notification_tap_resume_browser.py, on the argv road and no module refused, and the message REPORTS
        each road's count, the module count and the plant-table row count at whatever size the tree has, so a change
        of population is visible here and fails nothing by itself. The head's positives and negatives: snippets with
        no import of subprocess, so the library is read by its spelling as an unbound name (the stated fallback).
        PLANT_TABLE: every row run and held to its label, the site's LINE held to the planted call's, the road held to
        the label's, the refusal's message held to name the call's line and both declarations, and every row off its
        label named in the one failure (a refusal of a row labelled otherwise among them). The listed residual: a
        helper's call, a passthrough's splatted parameter, a star import's name, a class attribute read through the
        class name, a comprehension's parameter iterable, a keywords splat handed alone, a parameter extended in place,
        a staticmethod's attribute read through a parameter named self (row N42), a text spelling a name bound to the
        kernel's name (row N70) and a Python child's -c program that runs the kernel as __main__ through runpy (row
        N93) are no site and each is under `unresolved` with its line, text and kind; a comprehension's own target is
        not, and neither is a builtin's call, a consumer."""
        roads = spawn_roads(HERE, skip=TREE_SKIP)
        counts = {r: sum(1 for road, _, _ in roads.values() if road == r) for r in ("argv", "binding", "neither", "refused")}
        report = ("the roads table over %d modules under tests/ (python tests/test_hermetic_kernel_postal.py --roads): argv %d, "
                  "binding %d, neither %d, refused %d; PLANT_TABLE %d rows"
                  % (len(roads), counts["argv"], counts["binding"], counts["neither"], counts["refused"], len(PLANT_TABLE)))
        for lab in ("test_federation_missing_served.py", "test_notification_tap_resume_browser.py"):
            self.assertEqual(roads.get(lab, ("absent from the table",))[0], "argv",
                             "%s starts a lab kernel by an argv element that is the path as written; %s" % (lab, report))
        self.assertEqual([n for n, (road, _, _) in roads.items() if road == "refused"], [],
                         "a module under tests/ binds an argv name both to the kernel's path and to something else; %s" % report)
        # the head's shapes: a list literal, a path joined or divided, a call split across lines, run as well as Popen
        for src in ('subprocess.Popen([os.path.join(BIN, "romp-kernel")], env=env)',
                    'subprocess.run(\n    [sys.executable, str(BIN / "romp-kernel")],\n    capture_output=True)',
                    'Popen(["python3", "bin/romp-kernel"])',
                    'subprocess.check_output([os.path.join(BIN, "romp"), "up", "--foreground"])',
                    'KERNEL = os.path.join(BIN, "romp-kernel")\nproc = subprocess.Popen([sys.executable, KERNEL], env=env)'):
            self.assertTrue(_spawns_kernel(src), "a kernel spawn the labs write, the library by its spelling (unbound): " + src)
        for src in ('subprocess.run(["node", "esbuild.js"], cwd=EXT)',
                    'subprocess.run(["bin/romp-postal-service", "ensure"])',
                    'subprocess.run([os.path.join(BIN, "romp-judge"), "--once"])',
                    'load_source("romp_kernel", os.path.join(BIN, "romp-kernel"))'):
            self.assertFalse(_spawns_kernel(src), "not a kernel spawn (a build, the other scripts, an in-process load): " + src)
        # the labelled table: every row read, and each row off its label named in the one failure, a refusal included
        roads_by_label = {"caught-by-argv": "argv", "caught-by-binding": "binding"}
        off = []
        for label, kind, site, src in PLANT_TABLE:
            try:
                sites, refusal = _kernel_spawn_sites(src, "planted.py"), None
            except UnreadableSpawn as e:
                sites, refusal = None, str(e)
            if kind == "refused-loud":
                call, path, other = site
                if refusal is None:
                    off.append("%s: two declarations that disagree are refused loudly, never read either way; read as %r" % (label, sites))
                    continue
                absent = [n for n in ("planted.py line %d:" % call, "(line %d:" % path, "(line %d:" % other) if n not in refusal]
                if absent:
                    off.append("%s: the refusal names the call's line and both declarations; %r not in: %s" % (label, absent, refusal))
            elif refusal is not None:
                off.append("%s: labelled %s and refused: %s" % (label, kind, refusal))
            elif kind == "no-spawn":
                if sites:
                    off.append("%s: no kernel spawn (keyed on the argv's elements resolved to their bindings, never on a word of the "
                               "argv's text); read %r" % (label, sites))
            elif [(line, road) for line, _, road in sites] != [(site, roads_by_label[kind])]:
                off.append("%s: one site, at the planted call's line %d, by the %s road; read %r" % (label, site, roads_by_label[kind], sites))
        self.assertEqual(off, [], "PLANT_TABLE rows off their label (%s):\n%s" % (report, "\n".join(off)))
        self.assertEqual(sorted({kind for _, kind, _, _ in PLANT_TABLE}), ["caught-by-argv", "caught-by-binding", "no-spawn", "refused-loud"],
                         "the table carries every label at least once")
        # the residual, listed (keyed on the callee's or the name's declarations: none readable, or none at all and no builtin)
        for src, listed in (('def kpath():\n    return os.path.join(BIN, "romp-kernel")\nsubprocess.run([kpath()])', (3, "kpath", "call of def")),
                            ('def fake_run(*a, **kw):\n    return subprocess.run(*a, **kw)', (2, "a", "parameter")),
                            ('from helpers import *\nsubprocess.run([kernel_argv()])', (2, "kernel_argv", "call of an unbound name")),
                            ('class Lab:\n    K = os.path.join(BIN, "romp-kernel")\nsubprocess.run([Lab.K])', (3, "Lab.K", "attribute of class")),
                            ('def start(args):\n    return subprocess.run([a for a in args])', (2, "args", "parameter")),
                            ('def start(**kw):\n    return subprocess.run(**kw)', (2, "kw", "keywords splat of parameter")),
                            ('def start(cmd):\n    cmd += ["--serve"]\n    return subprocess.run(cmd)', (3, "cmd", "parameter")),
                            (next(src for label, _, _, src in PLANT_TABLE if label.startswith("N42 ")),
                             (5, "self.kernel", "attribute of parameter")),
                            (next(src for label, _, _, src in PLANT_TABLE if label.startswith("N70 ")),
                             (2, "'KERNEL'", "text spelling a name bound to romp-kernel")),
                            (next(src for label, _, _, src in PLANT_TABLE if label.startswith("N93 ")),
                             (3, '"import runpy; runpy.run_path(%r, run_name=\'__main__\')" % KERNEL',
                              "-c program the scan cannot read as starting no process"))):
            sites, unresolved = _scan_plant(src)
            self.assertEqual(sites, [], "no site, the value unread (keyed on the declarations the scan resolves to): " + src)
            self.assertIn(listed, unresolved, "the unread value is listed under the residual as (line, text, kind), never passed "
                          "over silently (keyed on the declarations' kinds): %r for %s" % (unresolved, src))
        _, unresolved = _scan_plant('def start(args):\n    return subprocess.run([str(a) for a in args])')
        self.assertEqual([text for _, text, _ in unresolved], ["args"], "a comprehension's own target is never resolved, so "
                         "it is never listed; its iterable, a parameter, is (keyed on the comprehension's scope): %r" % unresolved)
        read = _scan_plant('subprocess.run([repr(BIN), open(BIN).read()])')
        self.assertEqual(read, ([], []), "a builtin's call and a consumer's method are read as no path and not listed (keyed on "
                         "the callee being a builtin, or an attribute): %r" % (read,))

    def test_the_offender_census_names_a_planted_launch_by_its_line_and_not_a_planted_word_collision(self):
        """The composition the trio test runs (_kernel_spawn_offenders: the spawn scan and the trio read together, over a
        directory of modules) and the roads table (spawn_roads), over planted modules: the module that launches the
        kernel through a path bound across two lines with no trio is the one offender, named with its file, the line of
        the call and the argv; the same launch under kernel_env is none; eight modules whose only tie to the kernel is a
        local bound to its path, or to text spelling it, beside a nested pytest argv carrying the local's name as a flag
        or a word are none (the regex census named every one of them and missed the launch, the red-before of
        2026-09-21); the roads label the two launches binding and the eight neither. The --roads arm (_print_roads)
        over the same directory prints a line per module with the road the roads table gives it and one line per
        unresolved entry, and every count on its summary line equals what spawn_roads derives over that directory, its
        offender count what _kernel_spawn_offenders derives (review round 9: the arm the census's cited figures come
        from was run by no test). A separate directory holds a module that binds one name to the path and to a pytest
        argv in one function: the census is loud on it, naming the module and both lines, and the roads table labels
        it refused. Both directories are read by _read_root, the function the real tree's read is, so a read that
        dropped a refused row, or labelled it otherwise, reds here as it would over the tree."""
        d = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, d, True)
        head = 'import os, subprocess, sys, unittest\nBIN = "/tmp/TESTHOST/bin"\n\nclass T(unittest.TestCase):\n    def test_a(self):\n'
        launch = '        KERNEL = os.path.join(\n            BIN, "romp-kernel")\n        subprocess.Popen([KERNEL], env=%s)\n'
        pytest_argv = '        subprocess.run([sys.executable, "-m", "pytest", %s"tests/test_other.py"])\n'
        planted = {"test_launch_no_trio.py": head + launch % "{}",
                   "test_launch_kernel_env.py": head + launch % "kernel_env(d, c, x, 1, t)"}
        for local, flag in (("p", '"-p", "no:cacheprovider", '), ("x", '"-x", '), ("k", '"-k", "boot", '), ("path", '"path/of/tests", '),
                            ("kernel", '"kernel", '), ("src", '"src/main.ts", '), ("lines", '"-k", "lines", ')):
            planted["test_collide_%s.py" % local] = (head + '        %s = os.path.join(BIN, "romp-kernel")\n        open(%s).read()\n' % (local, local)
                                                    + pytest_argv % flag)
        planted["test_collide_text.py"] = head + '        p = "os.path.join(BIN, \'romp-kernel\')"\n' + pytest_argv % '"-p", "tests.conftest", '
        for name, text in planted.items():
            with open(os.path.join(d, name), "w", encoding="utf-8") as f:
                f.write(text)
        text = planted["test_launch_no_trio.py"]
        planted_line = text[:text.index("subprocess.Popen")].count("\n") + 1
        self.assertEqual(_kernel_spawn_offenders(d), [("test_launch_no_trio.py", planted_line, "[KERNEL]")],
                         "the one offender, named with the line of the planted call (the two-line binding read through KERNEL)")
        self.assertEqual(_kernel_spawn_offenders(d, skip=("test_launch_no_trio.py",)), [], "the launch under kernel_env and the eight collisions are none")
        roads = {name: road for name, (road, _, _) in spawn_roads(d).items()}
        self.assertEqual(roads, dict({n: "neither" for n in planted}, **{"test_launch_no_trio.py": "binding", "test_launch_kernel_env.py": "binding"}),
                         "the roads table over the planted directory: the two launches by the binding road, the eight collisions neither")
        printed = io.StringIO()
        with contextlib.redirect_stdout(printed):
            _print_roads(d)
        out = printed.getvalue().splitlines()
        table = spawn_roads(d)
        entries = [(name, line, text, kind) for name, (_, _, unresolved) in table.items() for line, text, kind in unresolved]
        spawn_sites = [r for _, sites, _ in table.values() for _, _, r in sites]
        self.assertTrue(entries and spawn_sites, "the planted directory gives no unresolved entry or no spawn site: the "
                        "summary's counts would be held against an empty population")
        by_kind = {}
        for _, _, _, kind in entries:
            by_kind[kind] = by_kind.get(kind, 0) + 1
        derived = dict({r: sum(1 for road, _, _ in table.values() if road == r) for r in ("argv", "binding", "neither", "refused")},
                       modules=len(table), sites=len(spawn_sites), argv_sites=spawn_sites.count("argv"),
                       binding_sites=spawn_sites.count("binding"), offenders=len(_kernel_spawn_offenders(d)),
                       unresolved=len(entries), calls=len({(name, line) for name, line, _, _ in entries}),
                       unresolved_modules=len({name for name, _, _, _ in entries}), kinds=by_kind,
                       executable=sum(1 for _, _, text, _ in entries if text == "sys.executable"))
        summary = [re.fullmatch(r"# summary: modules (\d+); argv (\d+); binding (\d+); neither (\d+); refused (\d+); spawn sites "
                                r"(\d+) \(argv (\d+), binding (\d+)\); offenders (\d+); unresolved names (\d+) in (\d+) calls of "
                                r"(\d+) modules by kind (\{.*\}); sys\.executable (\d+) of them", line) for line in out]
        summary = [m for m in summary if m]
        self.assertEqual(len(summary), 1, "the --roads arm prints one summary line in the shape this test reads: %r" % out[-1:])
        fields = ("modules", "argv", "binding", "neither", "refused", "sites", "argv_sites", "binding_sites", "offenders",
                  "unresolved", "calls", "unresolved_modules", "kinds", "executable")
        values = summary[0].groups()
        self.assertEqual(dict(zip(fields, [int(v) for v in values[:12]] + [ast.literal_eval(values[12]), int(values[13])])), derived,
                         "the --roads summary over the planted directory against spawn_roads over it (modules, each road, the "
                         "sites by road, the unresolved entries, their calls, modules and kinds, sys.executable among them) and "
                         "_kernel_spawn_offenders over it (the offenders)")
        opens = out.index(next(line for line in out if line.startswith("# unresolved:")))
        self.assertEqual({line.split()[0]: line.split()[1] for line in out[:opens]}, {name: road for name, (road, _, _) in table.items()},
                         "the --roads module lines (module, road) against the roads table")
        self.assertEqual(len(out) - opens - 2, len(entries), "the --roads arm prints one line per unresolved entry between "
                         "its unresolved header and its summary: %r" % out[opens:])
        loud_dir = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, loud_dir, True)
        rebinding = (head + '        k = os.path.join(BIN, "romp-kernel")\n        k = [sys.executable, "-m", "pytest", "-k", "boot"]\n'
                     + '        subprocess.run(k)\n')
        with open(os.path.join(loud_dir, "test_rebinding.py"), "w", encoding="utf-8") as f:
            f.write(rebinding)
        with self.assertRaises(UnreadableSpawn, msg="a name bound to the path and to a pytest argv in one function is refused loudly by the census") as loud:
            _kernel_spawn_offenders(loud_dir)
        for needle in ("test_rebinding.py line 8:", "(line 6:", "(line 7:"):
            self.assertIn(needle, str(loud.exception), "the refusal names the module, the call's line and both declarations: %s" % loud.exception)
        self.assertEqual([road for road, _, _ in spawn_roads(loud_dir).values()], ["refused"], "the roads table labels the module refused")

    def test_the_scan_covers_every_call_the_regex_census_it_replaced_flagged(self):
        """The old-versus-new comparison (review round 9: a replacement instrument covers at least what it replaced, and
        the proof is the old and the new run over one population). The census the scan replaced (_round8_regex_census,
        round 8's regex pair copied verbatim) and the scan run over every module the trio test reads and every
        PLANT_TABLE row, under one rule (_regex_scan_comparison): for each call the regex flags, the scan gives a site at
        the call's line, or a listed entry at that line whose expression contains the match (the scan's own entries, and
        the entries of the hand listing, LISTED_BY_HAND, each covering the matches on the line of its module it names by
        number and text), or refuses the module (UnreadableSpawn, red in the trio test); any other match at a call is
        named; a regex hit at no call is accounted for when the module has a site, is refused, or has a listed entry
        containing it, and is named otherwise. No proof inside a reader excuses a hit, and no reader carries an
        exemption keyed on a spelling. A named match reds the case, naming the module or row, the line and the match,
        over the tree as over the rows, except in the rows whose label says the comparison names them, and each of those
        must carry at least one (a launch, or a clean shape the scan neither reads as a site nor lists: the cost of
        failing closed the module docstring states).
        The rows with a regex hit at no call are held the same way, among them a comment and a docstring (N11, N12) and
        a program held in a string that is exec'd or written to a script file a test runs (N116, N117), named at labels
        that say so, and B71, B74, A35 and A45 (each module has a site) and N89 (its listed program contains the hit),
        which name nothing. A listed entry covers a match it holds whole, start and end (PR #850's eleventh review
        round): each row whose label says an entry the scan lists holds the start of the match and not its end (N118 to
        N125) carries such an entry at a call and is named at exactly the matches such entries hold the start of. A hand
        entry that covers no match reds the case, naming the entry. A row whose label says the regex missed it too
        carries no call the regex flags. Reported and asserting nothing: the rows and the
        modules whose sites the regex missed (B1 and the rest of round 8's silent half). The tree half is read from the
        roads table (_roads_table), whose one read compared each module with the scan it ran for the roads, so this case
        scans no module of the tree again. Then plants the comparison must name: consumer calls the regex flags
        (os.path.relpath of a name bound to the path, beside a listed sys.executable that does not cover it, and of the
        path spelled inline); names bound on one line that reach the binding the regex read (through .replace, which the
        scan does not read, and through os.path.relpath, whose arguments it does); the CLI in a shell string handed a
        verb the shell expands ($VERB); and -c programs the scan neither reads as a site nor lists (a Python child that
        loads the kernel and starts another process, one that starts a process through os.system, a %s placeholder read
        as code, a program that does not parse as Python, a shell's program that Python would parse)."""
        table = _roads_table(HERE, TREE_SKIP)
        dropped, tree_flagged, rows_flagged, missed, not_calls, tree_missed, tree_not_calls = [], 0, 0, [], [], [], []
        for name, (d, rm, nc, flagged, _) in sorted(table.compared.items()):
            dropped += [(name,) + x for x in d]   # a named hit at no call among them
            tree_flagged += flagged
            tree_missed += ["%s:%s" % (name, ",".join(map(str, rm)))] if rm else []
            tree_not_calls += [name] if nc else []
        named, also_missed = {}, {}
        for label, _, _, src in PLANT_TABLE:
            row = label.split()[0]
            c = _regex_scan_comparison(src, "planted.py", scan_all=True)
            if "the comparison names it" in label:
                named[row] = [(line, match) for line, match, _ in c.dropped]
            else:
                dropped += [(label,) + x for x in c.dropped]
            if "the regex missed it too" in label:
                also_missed[row] = c.flagged
            rows_flagged += c.flagged
            missed += [row] if c.missed else []
            not_calls += [row] if c.not_calls else []
        self.assertTrue(tree_flagged and rows_flagged, "the regex census flagged no call over the tree (%d) or the rows (%d): "
                        "the comparison's population is empty" % (tree_flagged, rows_flagged))
        self.assertTrue(also_missed and not any(also_missed.values()), "the rows whose label says the regex missed them too, "
                        "each with no call the regex flags (row: flagged calls): %r" % also_missed)
        self.assertTrue(named, "no row's label says the comparison names it")
        self.assertEqual([row for row, matches in named.items() if not matches], [], "rows whose label says the comparison "
                         "names them, with no match named (a site, a listed entry containing each match, or a refusal took "
                         "every one)")
        held = {}   # row -> the matches at a call that an entry the scan lists there holds the start of and not the end
        for label, _, _, src in PLANT_TABLE:
            if "holds the start of the match and not its end" in label:
                tree = _parse_text(src, "planted.py")
                scan = _SpawnScan(tree, "planted.py")
                scan.sites()
                hits, at = _regex_hits_at_calls(src, tree)
                held[label.split()[0]] = [
                    (call.lineno, text) for call, _, matches in hits if call is not None for offset, text in matches
                    if any(at(n.lineno, n.col_offset) <= offset < at(n.end_lineno, n.end_col_offset) < offset + len(text)
                           for line, n in scan.unresolved_nodes if line == call.lineno)]
                scan.bindings.release()
                del tree, scan
        self.assertTrue(held, "no row's label says an entry the scan lists holds the start of the match and not its end")
        self.assertEqual([row for row, matches in held.items() if not matches or named.get(row) != matches], [],
                         "rows whose label says an entry the scan lists holds the start of the match and not its end, with "
                         "no such entry at a call or not named at exactly the matches such an entry holds the start of (an "
                         "entry covers a match it holds whole); row: (those matches, the named): %r"
                         % {row: (matches, named.get(row)) for row, matches in held.items()})
        self.assertEqual(_hand_entries_covering_nothing(table.compared.values(), LISTED_BY_HAND), [], "entries of the hand "
                         "listing (LISTED_BY_HAND) that cover no match of the round-8 regex census over the tree: the "
                         "listing holds only lines that exist ((module, line, text, kind, reason))")
        self.assertEqual(dropped, [], "matches of the round-8 regex census that the scan neither reads as a site nor lists, "
                         "and that no entry of the hand listing covers, each named ((module or row, line, match, call)): at a "
                         "call the regex flags, or at no call in a module with no site that no refusal and no listed entry "
                         "accounts for: %r. Over %d flagged calls of the tree and %d of the rows; the rows whose sites the "
                         "regex missed: %s; the modules whose sites it missed (module:lines): %s; the modules and the rows "
                         "with a regex hit at no call, each accounted for or named: %s, %s"
                         % (dropped, tree_flagged, rows_flagged, missed, tree_missed, tree_not_calls, not_calls))
        consumer = 'KERNEL = os.path.join(BIN, "romp-kernel")\nsubprocess.run([sys.executable, os.path.relpath(KERNEL)])'
        sites, unresolved = _scan_plant(consumer)
        self.assertEqual((sites, [text for line, text, _ in unresolved if line == 2]), ([], ["sys.executable"]),
                         "the consumer plant: no site, and sys.executable the one entry listed at the call")
        self.assertEqual([(line, match) for line, match, _ in _regex_scan_comparison(consumer, "planted.py")[0]],
                         [(2, "KERNEL")], "a consumer call the regex flags is dropped by the scan, and the comparison names it "
                         "(the listed sys.executable at that call does not contain the match)")
        for plant, match, what in (
                ('subprocess.run([sys.executable, os.path.relpath(os.path.join(BIN, "romp-kernel"))])', (1, "romp-kernel"),
                 "a consumer call whose argument spells the path"),
                ('KERNEL = os.path.join(BIN, "romp-kernel").replace("//", "/")\nsubprocess.Popen([KERNEL, "--serve"])', (2, "KERNEL"),
                 "a name bound on one line through a method the scan does not read (.replace), reaching the binding the regex read"),
                ('K = os.path.relpath(os.path.join(BIN, "romp-kernel"))\nsubprocess.run([sys.executable, K])', (2, "K"),
                 "a name bound on one line to a consumer's value, whose arguments the scan reads as holding the path")):
            self.assertEqual(_kernel_spawn_sites(plant, "planted.py"), [], "%s: the scan reads no site: %s" % (what, plant))
            self.assertEqual([(line, m) for line, m, _ in _regex_scan_comparison(plant, "planted.py")[0]], [match],
                             "%s: the regex flags it, the scan reads no site and lists no entry containing the match, so "
                             "the comparison names it: %s" % (what, plant))
        verb = 'subprocess.Popen("bin/romp $VERB", shell=True)'
        self.assertEqual(_kernel_spawn_sites(verb, "planted.py"), [], "the CLI handed a verb the shell expands: no site")
        self.assertEqual([(line, m) for line, m, _ in _regex_scan_comparison(verb, "planted.py")[0]], [(1, "bin/romp")],
                         "the CLI handed a verb the shell expands ($VERB) is named: the scan reads no site and lists no "
                         "entry containing the match")
        for plant, what in (
                ('subprocess.run([sys.executable, "-c", "km = load_source(\'k\', \'bin/romp-kernel\'); import subprocess; '
                 'subprocess.run([\'git\', \'status\'])"])', "a Python -c child that loads the kernel and starts another process"),
                ('subprocess.run([sys.executable, "-c", "import os; os.system(\\"exec \'bin/romp-kernel\' --serve\\")"])',
                 "a Python -c child that starts a process outside the subprocess module (os.system), the path quoted in its command"),
                ('subprocess.run([sys.executable, "-c", "x = %s" % "__import__(\'os\').system(\'bin/romp-kernel\')"])',
                 "a -c program with a %s placeholder where Python reads a name, the text filling it unread"),
                ('subprocess.run([sys.executable, "-c", "exec \'bin/romp-kernel\' --serve"])',
                 "a Python child's -c program that does not parse as Python"),
                ('subprocess.run(["sh", "-c", "bin/romp-kernel.real"])',
                 "a shell's -c program that Python would parse (a shell's program is no Python child)")):
            self.assertEqual(_kernel_spawn_sites(plant, "planted.py"), [], "%s: the scan reads no site: %s" % (what, plant))
            self.assertEqual([(line, m) for line, m, _ in _regex_scan_comparison(plant, "planted.py")[0]], [(1, "romp-kernel")],
                             "%s: the scan reads no site and lists no entry containing the match, so the comparison names "
                             "it: %s" % (what, plant))

    def test_a_line_listed_by_hand_covers_the_match_on_it_and_an_entry_that_covers_none_is_named(self):
        """THE HAND LISTING'S PIN (PR #850's tenth review round; keyed on the module and the line in its eleventh). Over
        plant directories read by _read_root (the function the real tree's read is). A module whose one clean line the
        round-8 regex matches at a call and the scan does not read as a site (the CLI with refresh) is named by the
        comparison with no entry; with a hand entry for that line of that module, the entry covers the match, nothing is
        named, and --roads prints the entry under `# unresolved:` with its kind and reason. An entry covers the matches
        on its own line of its own module only: a second line of that module with the same text, where a local of the
        same name is a helper's return given the kernel's path (a launch the scan neither reads as a site nor lists, the
        shape of row N111), is named while the entry covers the first; and a second module holding the same text at the
        same line number, the same launch, is named, since the read hands each module only its own entries (the module
        filter in _read_root). The same entry over the covered module with that line now holding other text, two real
        launches of row N105's shape on the entry's line number and the next, covers no match: the check the comparison
        case runs on LISTED_BY_HAND (_hand_entries_covering_nothing) names it, and both launches are named. The reds are
        mutant runs: with the comparison's read of the entries removed, the covered module is named; with the line's
        number or its text not read, the module filter removed, or an entry covering every match, a launch is covered."""
        line = 'subprocess.run(["bin/romp", "refresh"])'
        entry = ("test_listed.py", 5, line, "the CLI with a verb outside KERNEL_VERBS", "refresh acts through a manager already running")
        d = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, d, True)
        with open(os.path.join(d, "test_listed.py"), "w", encoding="utf-8") as f:
            f.write("import subprocess\n\n\ndef test_a():\n    %s\n" % line)
        bare = _read_root(d, listing=()).table
        self.assertEqual(([(n, m) for n, m, _ in bare.compared["test_listed.py"][0]], bare.roads["test_listed.py"][1]),
                         ([(5, "bin/romp")], ()), "with no entry, the clean line's match is named and the scan reads no site")
        listed = _read_root(d, listing=(entry,)).table
        self.assertEqual((listed.compared["test_listed.py"][0], listed.compared["test_listed.py"][4]), ((), (entry,)),
                         "the entry covers the match on its line: nothing named, and the entry among those that covered one")
        self.assertEqual(_hand_entries_covering_nothing(listed.compared.values(), (entry,)), [], "an entry that covers a "
                         "match is no fault")
        printed = io.StringIO()
        with contextlib.redirect_stdout(printed):
            _print_roads(d, listing=(entry,))
        out = printed.getvalue().splitlines()
        opens = out.index(next(o for o in out if o.startswith("# unresolved:")))
        self.assertEqual(out[opens + 1:-1], ["test_listed.py:%d %s (%s; listed by hand: %s)" % entry[1:]], "--roads prints "
                         "the entry under the unresolved heading with its line, its kind and its reason, and the module's "
                         "scan lists nothing")
        call = 'subprocess.Popen([K, "--serve"])'
        stub = ("test_twice.py", 8, call, "a stub script", "romp-kernel-stub is a stand-in that starts no kernel")
        head = "import os\nimport subprocess\nfrom helpers import HERE, staged\n\n\n"
        launch = 'def test_launch():\n    K = staged("bin/romp-kernel")\n    %s\n' % call
        twice = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, twice, True)
        with open(os.path.join(twice, "test_twice.py"), "w", encoding="utf-8") as f:
            f.write(head + 'def test_stub():\n    K = os.path.join(HERE, "romp-kernel-stub")\n    %s\n\n\n' % call + launch)
        with open(os.path.join(twice, "test_other.py"), "w", encoding="utf-8") as f:
            f.write(head + launch)
        bare = _read_root(twice, listing=()).table
        self.assertEqual({m: ([(n, x) for n, x, _ in bare.compared[m][0]], bare.roads[m][1]) for m in ("test_twice.py", "test_other.py")},
                         {"test_twice.py": ([(8, "K"), (8, "K"), (13, "K"), (13, "K")], ()), "test_other.py": ([(8, "K")], ())},
                         "with no entry, each match of the three lines with the same text is named (in the module that binds "
                         "K twice, the regex's two bindings of K match each line twice) and the scan reads no site")
        read = _read_root(twice, listing=(stub,)).table
        self.assertEqual({m: ([(n, x) for n, x, _ in read.compared[m][0]], read.compared[m][4]) for m in ("test_twice.py", "test_other.py")},
                         {"test_twice.py": ([(13, "K"), (13, "K")], (stub,)), "test_other.py": ([(8, "K")], ())},
                         "the entry covers its own line of its own module only: the launch on a second line with the same "
                         "text, and the launch in another module holding that text on the same line number, are named")
        stale = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, stale, True)
        with open(os.path.join(stale, "test_listed.py"), "w", encoding="utf-8") as f:
            f.write('import subprocess\n\n\ndef test_a():\n    subprocess.run("bin/romp help; eval \'bin/romp up\'", shell=True)\n'
                    '    subprocess.run("bin/romp status; bash -c \'bin/romp up\'", shell=True)\n')
        table = _read_root(stale, listing=(entry,)).table
        self.assertEqual(_hand_entries_covering_nothing(table.compared.values(), (entry,)), [entry], "the same entry over the "
                         "module with its line now holding other text covers no match, and the comparison case's check names it")
        self.assertEqual([(n, m) for n, m, _ in table.compared["test_listed.py"][0]],
                         [(5, "bin/romp"), (5, "bin/romp"), (6, "bin/romp"), (6, "bin/romp")], "the two launches in that "
                         "module, on the entry's line number and on the next, are named: the entry covers neither")

    def test_every_kernel_verb_is_a_verb_bin_romp_dispatches(self):
        """Existence only: each verb in KERNEL_VERBS is one bin/romp's top-level dispatch has (_bin_romp_verbs, read from
        bin/romp's text), so the CLI road never narrows to a verb the CLI lacks (review round 9: it read `kernel`,
        which bin/romp answers with an unknown-command exit). Whether a dispatched verb starts a kernel is not read
        here: row A3 (`romp up --foreground`, caught by the argv) holds that reading. The reader is run over a
        synthetic dispatch too, one of each form it reads and the forms it must not."""
        text = _bin_romp_text()
        verbs, _ = _bin_romp_verbs(text)
        self.assertTrue(verbs, "the dispatch read found no verb in bin/romp: the reader no longer matches its dispatch")
        self.assertEqual(_verbs_bin_romp_lacks(KERNEL_VERBS, text), [],
                         "KERNEL_VERBS names a verb bin/romp's top-level dispatch does not have (existence only; row A3 holds "
                         "whether the scan reads `romp up` as a kernel spawn); dispatched: %s" % sorted(verbs))
        self.assertEqual(_verbs_bin_romp_lacks(KERNEL_VERBS | {"kernel"}, text), ["kernel"], "a planted verb bin/romp lacks is named")
        synthetic = ('if [[ "${1:-}" == "alpha" || "${1:-}" == "--alpha" ]]; then\n    exit 0\nfi\n'
                     'if [[ "${1:-}" =~ ^(beta|gamma)$ ]]; then\n    exit 0\nfi\n'
                     'case "${1:-}" in\n    delta|--delta)   # an arm (with a comment)\n        case "$2" in\n            inner) ;;\n'
                     '        esac\n        ;;\n    -*) exit 2 ;;\n    *) exit 2 ;;\nesac\nif [[ "$2" == "omega" ]]; then\n    exit 0\nfi\n')
        self.assertEqual(_verbs_bin_romp_lacks({"alpha", "--alpha", "beta", "gamma", "delta", "--delta", "inner", "omega", "-x"}, synthetic),
                         ["-x", "inner", "omega"], "the reader takes the == and =~ tests of the first word and the top-level "
                         "arms, and neither a nested case's arm, a test of another word nor a catch-all arm")

    def test_the_tree_is_parsed_once_per_file_in_the_module_run_and_read_once(self):
        """THE PARSE PIN (PR #850's review round 9, E ruled again): the trio test, the guard test and _peers_writers
        share one parse of each file per module run, counted by the module's own counter: _PARSES, which _parse_text
        moves once per parse against the text's key (_text_key), so a parse counts whatever filename it was given. Every
        tree the module builds by a road it spells in its own text as one of the spellings _TREE_BUILDERS holds comes
        from _parse_text, or from a def of fork PR #894's that _OWN_TREE_ROADS names, whose parses this counter does not
        see (the helpers pin); a road by any other spelling is not read, among them getattr, __import__, a
        name bound at run time, compile's flag by value, and another module's function that parses (ast.literal_eval,
        which the module calls). Their reads (_kernel_spawn_offenders, spawn_roads, _peers_writers), with the --roads
        arm's (_print_roads) and the comparison case's (_roads_table), answer from the module run's one read of the tree
        (_tree_read, made by whichever of them ran first) and hand back its objects; the module run read the tree once
        (_READS); the read recorded a text key for every file it parsed and no other (its `keys`), its population every
        .py under tests/, walked recursively, with the table's (the modules directly under tests/ but this one) inside
        it; and each of those texts, as the read parsed it, was parsed once for each file that holds it
        (_parse_count_faults over the read's keys, so a file edited after the read is held to the text the read parsed,
        PR #850's tenth review round). The one other parse of a file of the tree through _parse_text is the placement
        test's, of the tunnels module, once per run of that test (_PLACEMENT_PARSES, under the key of the text it
        parsed), and nothing keeps its tree (the release pin): that text's expected count adds those runs. The census
        parses each file of the tree once more by its own road (_own_tree, counted in _OWN_PARSES, which its parse-once
        pins hold), and other defs _OWN_TREE_ROADS names parse a file of the tree for a pin of their own
        (tests/conftest.py, this module): _PARSES counts neither. The red: a reader that parses the tree
        again through _parse_text moves the counter past the expected count of each file it reads. Read here, the count
        sees the parses of the tests that ran before this one in the process; tearDownModule reads the same count over
        the whole module run (_module_end_faults), so a re-parse in a test that runs after this one, or on another
        worker under xdist, fails the module's teardown. The read's population is also compared with a walk of tests/
        taken here (_tree_module_paths): a file added or removed under tests/ during the module's run reds it, a
        stated residual; no test writes a .py under tests/, so the trigger is a person or a session editing the tree
        mid-run."""
        read = _tree_read()
        _kernel_spawn_offenders(HERE, skip=TREE_SKIP)                  # the trio test's read
        roads = spawn_roads(HERE, skip=TREE_SKIP)                      # the guard test's
        _peers_writers()                                               # the read's environment writes
        with contextlib.redirect_stdout(io.StringIO()):
            _print_roads(HERE, skip=TREE_SKIP)                          # the --roads arm's
        again = _roads_table(HERE, TREE_SKIP)                          # the comparison case's
        self.assertEqual(_READS[0], 1, "the tree was read %d times in this module run, not once (_READS)" % _READS[0])
        self.assertIs(roads, read.table.roads, "the guard test reads the table of the module run's one read")
        self.assertIs(again, read.table, "the comparison case reads the same table")
        self.assertTrue(read.table.paths and len(read.table.paths) == len(read.table.roads), "the table read no module, or "
                        "its paths and its rows disagree: %d paths, %d rows" % (len(read.table.paths), len(read.table.roads)))
        self.assertTrue(set(read.table.paths) <= set(read.paths), "the read's walk of tests/ holds every module the table read")
        self.assertEqual(sorted(read.keys), sorted(set(read.paths) | set(read.table.paths)), "the read recorded a text key "
                         "for every file it parsed and for no other: the population _parse_count_faults holds _PARSES to")
        self.assertEqual(list(read.paths), _tree_module_paths(), "the read's population against a walk of tests/ taken "
                         "now (_tree_module_paths); a file added or removed under tests/ during the module's run reds this, "
                         "the stated residual")
        self.assertEqual(_parse_count_faults(), [], "texts of the tree's read, as it parsed them, parsed other than expected "
                         "in this module run, by the module's counter (_PARSES): (file, parses, expected: one per file that "
                         "holds the text for each read of the tree, and the placement test's parses of that text besides)")

    def test_an_aborted_read_of_the_tree_reports_where_it_stopped_and_expects_no_parse_count(self):
        """D (PR #850's eleventh review round): a read of the tree that raises is reported with the file it stopped at
        and the cause, and the parse check expects no count of it, where the check's no-read branch had named every
        file the read never reached as parsed 0 times against the reads counted, one per attempt, since each later test
        that reads the tree tried again (0 against 6 in the red named below). Over a scratch directory standing for
        tests/ (_tree_read's root): test_a.py parses, test_b.py does not, and test_c.py, after it in the read's order,
        is never reached. With the module's state emptied (_release) and put back after, and setUpModule's list kept for
        the module end's other checks: the read raises ReadAborted naming test_b.py and a SyntaxError; the module end's
        checks (_module_end_faults) report that abort and nothing else; and the parse check (_parse_count_faults) names
        nothing. Then test_b.py is made to parse and the tree read again in the same run: the read completes, and the
        checks still report the first read's abort alone (the two reads, the first stopped partway, would otherwise
        leave test_b.py and test_c.py at one parse against two). The red at the round-11 review head is the module run
        over a scratch copy of the checkout with a file under its tests/ that does not parse, whose teardown named every
        file the read never reached; here, a mutant that takes the abort out of the parse check reds this test with
        such rows. Last, a read of a directory that does not exist (_read_root, with count) raises ReadAborted with no
        file (where None, the message naming its start) and a FileNotFoundError as its cause, chained from it: the
        directory's listing is inside the read's abort (the red is the head before that, whose read raised the bare
        FileNotFoundError)."""
        d = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, d, True)
        scratch = os.path.join(d, "tests")
        os.mkdir(scratch)
        for name, text in (("test_a.py", "A = 1\n"), ("test_b.py", "def broken(:\n"), ("test_c.py", "C = 3\n")):
            with open(os.path.join(scratch, name), "w", encoding="utf-8") as f:
                f.write(text)
        at_start = list(_AT_START)
        self.addCleanup(_module_state_put_back())
        _release()
        _AT_START[:] = at_start
        with self.assertRaises(ReadAborted) as caught:
            _tree_read(scratch)
        self.assertEqual((caught.exception.where, type(caught.exception.cause).__name__), ("test_b.py", "SyntaxError"),
                         "the read raises ReadAborted naming the file it stopped at and the cause")
        aborted = ("the tree's read aborted in this module run, so no parse count is expected of it: stopped at test_b.py "
                   "(SyntaxError: ")
        faults = _module_end_faults()
        self.assertEqual(([f[:len(aborted)] for f in faults], len(faults)), ([aborted], 1), "the module end's checks after "
                         "an aborted read: the abort, with the file it stopped at and the cause, and nothing else: %r"
                         % [f[:1000] for f in faults])
        self.assertEqual(_parse_count_faults(), [], "the parse check after an aborted read names no file")
        with open(os.path.join(scratch, "test_b.py"), "w", encoding="utf-8") as f:
            f.write("B = 2\n")
        read = _tree_read(scratch)
        self.assertEqual((_READS[0], sorted(os.path.relpath(p, scratch) for p in read.paths)), (2, ["test_a.py", "test_b.py", "test_c.py"]),
                         "the second read of the run completes over every file")
        faults = _module_end_faults()
        self.assertEqual(([f[:len(aborted)] for f in faults], len(faults)), ([aborted], 1), "the module end's checks after "
                         "an aborted read and a read that completed: the first read's abort and nothing else: %r"
                         % [f[:1000] for f in faults])
        self.assertEqual(_parse_count_faults(), [], "the parse check after an aborted read and a read that completed names "
                         "no file")
        start = "the read stopped at its start: FileNotFoundError: "
        with self.assertRaises(ReadAborted) as caught:
            _read_root(os.path.join(d, "absent"), count=True)
        e = caught.exception
        self.assertEqual((e.where, type(e.cause).__name__, e.__cause__ is e.cause, str(e)[:len(start)]),
                         (None, "FileNotFoundError", True, start), "a read of a directory that does not exist raises "
                         "ReadAborted with no file, its message naming its start, and a FileNotFoundError as its "
                         "cause, chained from it")

    def test_the_tree_read_keeps_no_tree_and_no_bindings_and_leaves_plain_values(self):
        """THE RELEASE PIN (PR #850's review round 9, E ruled again: no tree and no Bindings object of the module
        outlives it, and the table is left as plain values). Every tree and Bindings the module builds by a road it
        spells in its own text as one of the spellings _TREE_BUILDERS holds comes from _parse_text or _bindings_of,
        each recording a weak reference (_TREES, _BINDINGS), or from a def of fork PR #894's that _OWN_TREE_ROADS names,
        which records none (the helpers pin; a road by any other spelling is not read, among them getattr, __import__, a
        name bound at run time, compile's flag by value, and another module's function that parses, ast.literal_eval,
        which the module calls). After the reads of the trio test, the guard test and _peers_writers (the module run's
        one read of the tree, made now or by an earlier test of the run): the records name
        a tree for every file of the read's population and a Bindings for every row of its table, so an empty record
        cannot pass; the read held one file's tree at a time, its most_trees (the most file trees alive at any file
        parse, _parse's count, reset when the read started) one, the tree just built (PR #850's tenth review round), and
        its born empty: no tree node or ast_bindings object it made was alive when its loop ended but the nodes of the
        trees the census parsed itself that its one owner holds (_census_held_nodes) (the objects of _HELD_TYPES alive
        then that were not in the list it took when it started, by class, read through
        gc.get_objects() with no collection, so a node kept without its root is seen; PR #850's eleventh review round);
        and the read's value, walked whole, holds nothing but tuples, strings, numbers, None and the dicts and frozensets
        that index them. Then _module_end_checks, the module end's check (fork PR #850's half of tearDownModule), is
        called here twice on the module's state, which is put back after each call so the later tests of the run read
        the same read. Over the state as it stands it
        raises nothing and leaves every container empty: every tree and Bindings recorded in the module run so far, the
        read's and those of every test that ran before this one in the process, is gone, no tree node or ast_bindings
        object made in the module's run so far is alive but the nodes of the trees the census parsed itself that its one
        owner holds, no read of the tree aborted in the module run, and no text of
        the tree's read, as the read parsed it, was parsed other than expected (_module_end_faults; _still_held reads
        each weak reference and the objects of those types alive now that are not in setUpModule's list, by class, with
        no collection: a weak reference sees only the tree root or the Bindings it refers to, the count by class also a
        node kept without its root). With a planted
        tree held, and planted statements held whose tree's root is dead, it raises naming the tree and not the
        statements' file, counts among the Assign nodes made and alive at least the statements held, and leaves the
        containers empty too. At the module's end tearDownModule runs the same checks over the whole run, so a tree kept
        by a test that runs after this one fails the module's teardown, and then drops what the module holds
        (_release). The reds are mutant runs: a cache at module scope that keeps each parse leaves every tree alive here
        and at the teardown; one that keeps each tree's statements and drops its root is counted at both; a read that
        keeps every file tree until it returns reds the most_trees assertion here and in the cycle test, and one that
        keeps each file tree's statements on a list until it returns reds the born assertion in both."""
        read = _tree_read()
        _kernel_spawn_offenders(HERE, skip=TREE_SKIP)                  # the trio test's read
        spawn_roads(HERE, skip=TREE_SKIP)                              # the guard test's
        _peers_writers()                                               # the read's environment writes
        population = {os.path.relpath(p, HERE) for p in set(read.paths) | set(read.table.paths)}
        self.assertEqual(sorted(population - {f for f, _ in _TREES}), [], "files of the read's population with no tree "
                         "recorded (_TREES)")
        self.assertEqual(sorted(set(read.table.roads) - {f for f, _ in _BINDINGS}), [], "rows of the read's table with no "
                         "Bindings recorded (_BINDINGS)")
        self.assertEqual(read.most_trees, 1, "the most file trees alive at any file parse of the tree's read (_parse's count, "
                         "reset when the read starts, the tree just built among them): one file's tree at a time is one")
        self.assertEqual(read.born, {}, "tree nodes and ast_bindings objects the tree's read made that were alive when its "
                         "loop ended, by class (gc.get_objects() against the list taken when it started, no collection): a "
                         "read that holds one file's tree at a time keeps none past its loop")
        foreign, stack = collections.Counter(), [read]
        while stack:   # loop-ok: each pass pops one value, and the read's value is finite and acyclic
            value = stack.pop()
            if isinstance(value, (tuple, frozenset)):
                stack.extend(value)
            elif isinstance(value, dict):
                stack.extend(value.keys())
                stack.extend(value.values())
            elif not isinstance(value, (str, int, float, type(None))):
                foreign[type(value).__name__] += 1
        self.assertEqual(dict(foreign), {}, "the tree's read holds values other than tuples, strings, numbers, None, dicts "
                         "and frozensets (type: count)")
        put_back = _module_state_put_back()

        def sizes():
            return {"_TREE_READ": len(_TREE_READ), "_PARSES": len(_PARSES), "_READS": _READS[0], "_TREES": len(_TREES),
                    "_BINDINGS": len(_BINDINGS), "_PLACEMENT_PARSES": len(_PLACEMENT_PARSES), "_AT_START": len(_AT_START),
                    "_FILE_TREES": len(_FILE_TREES), "_MOST_FILE_TREES": _MOST_FILE_TREES[0], "_ABORTED": len(_ABORTED)}

        try:
            _module_end_checks()                                       # the check: raises on any fault it reads
            left = sizes()
        finally:
            put_back()
        self.assertEqual(left, dict.fromkeys(left, 0), "_module_end_checks leaves the module holding something (container: size)")
        plant = _parse_text("x = 1\n", "release-pin-plant.py")
        statements = _parse_text("a = 1\n" * 50, "release-pin-statements.py").body   # the root dies here; its statements are held
        try:
            with self.assertRaises(AssertionError, msg="_module_end_checks with a tree of the module still held, and statements "
                                   "held whose root is dead") as caught:
                _module_end_checks()
            left = sizes()
        finally:
            put_back()
        message = str(caught.exception)
        self.assertIn("[('tree', 'release-pin-plant.py')]", message, "the teardown's red names the tree held")
        self.assertNotIn("release-pin-statements.py", message, "no weak reference names the statements' tree: its root is dead")
        assigns = re.search(r"made in this module's run are alive at its end .*by class: .*\bAssign (\d+)\b", message)
        self.assertTrue(assigns is not None and int(assigns.group(1)) >= len(statements), "the teardown's red counts, among "
                        "the Assign nodes made in the run and alive, at least the %d statements held without their root: %r"
                        % (len(statements), message[-400:]))
        self.assertEqual(left, dict.fromkeys(left, 0), "_module_end_checks that raises still drops what the module holds")
        del plant, statements

    def test_the_counts_leave_out_only_the_modules_the_census_parsed_itself_and_holds(self):
        """The reviewer's closing check of round 2 of fork PR #894, its first low: the two counts of what the module
        made and left alive, the read's `born` (_read_root) and the module end's (_still_held), leave out the nodes
        _census_held_nodes returns, and those are the nodes of each ast.Module in the census owner's "trees" held under
        a realpath the census's own parse counted (_OWN_PARSES), and of nothing else the owner holds. Three plants in
        "trees", each for a file of a fresh temporary directory: a module the census parses itself and holds
        (_own_tree), which is left out; a statement of a tree, held under the realpath the census's own parse counted
        for its file, in place of that file's tree, which is not an ast.Module and is counted; and a module parsed by
        _parse_text, whose parses _OWN_PARSES does not count, held under the realpath of a file the census never parsed,
        which is counted. Read as both counts read (_born over a list of what was alive before the plants and the nodes
        _census_held_nodes returns), what the plants made and left alive is the second plant's nodes and the third's, by
        class. The red: the leave-out as the closing check found it, every node of every value "trees" held, leaves out
        all three plants and counts nothing (under it, a read that kept each file's statements in "trees" under keys of
        its own ran green); leaving out every ast.Module whatever its key counts the second plant alone, and leaving out
        every value under a counted key counts the third alone. The test's cleanup takes the plants out of "trees", and
        no node is held in a local past the counts, so a red's traceback keeps none of them."""
        d = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, d, True)
        real = {}
        for name, text in (("held.py", "HELD = 1\n"), ("replaced.py", "REPLACED = 2\n"),
                           ("uncounted.py", "UNCOUNTED = 3\n")):
            path = os.path.join(d, name)
            with open(path, "w", encoding="utf-8") as f:
                f.write(text)
            real[name] = os.path.realpath(path)

        def take_out():
            for key in real.values():
                if _HELD:
                    _HELD[0]["trees"].pop(key, None)
        self.addCleanup(take_out)
        before = _held_alive()                     # held to the count below, so none of it dies and no id is reused
        _own_tree(real["held.py"])                                                   # parsed, counted and held
        _held()["trees"][real["replaced.py"]] = _own_tree(real["replaced.py"]).body[0]   # its module's root dies here
        _held()["trees"][real["uncounted.py"]] = _parse_text("UNCOUNTED = 3\n", "uncounted.py")
        nodes = _census_held_nodes()
        born = _born(before + nodes)
        left_out = {id(n) for n in nodes}
        plants = {name: (type(_held()["trees"][key]).__name__, id(_held()["trees"][key]) in left_out, _OWN_PARSES[key])
                  for name, key in real.items()}
        before = nodes = left_out = None           # no node past here: a red's traceback keeps none of them
        self.assertEqual((plants, born), ({"held.py": ("Module", True, 1), "replaced.py": ("Assign", False, 1),
                                           "uncounted.py": ("Module", False, 0)},
                                          {"Assign": 2, "Constant": 2, "Module": 1, "Name": 2}),
                         "first, each plant (the class of the value \"trees\" holds for the file, whether "
                         "_census_held_nodes leaves its root out, the census's own parses of the file): only the "
                         "module the census parsed itself and holds under a counted realpath is left out; then the "
                         "objects of _HELD_TYPES the plants made and left alive, by class, less the nodes "
                         "_census_held_nodes returns (_born, as the read's count and the module end's read it): the "
                         "statement held under a counted realpath and the module held under a realpath the census "
                         "never parsed, each Assign(Name, Constant), and that module's root")

    def test_every_tree_and_bindings_the_module_builds_comes_from_its_two_helpers(self):
        """THE HELPERS PIN, which the parse pin and the release pin stand on (they count and watch what _parse_text and
        _bindings_of record): in this module's source, read by its tokens (_tree_builder_spellings), every road to a
        tree or a Bindings spelled as one of the spellings _TREE_BUILDERS holds (among them ast.parse, compile's
        PyCF_ONLY_AST, `from ast import` and Bindings.of) lies inside _parse_text or _bindings_of, or inside a def of
        fork PR #894's that _OWN_TREE_ROADS names (the merged module's other roads, whose trees the parse pin does not
        count; the pin re-aimed so at the merged module on the reviewer's ruling of round 2 on fork PR #894, group C), the
        list equal to the defs outside the two helpers that spell a road, so it names none that spells no road; and each helper
        spells its own road once: outside those defs, the one ast.parse is _parse_text's and the one Bindings.of is
        _bindings_of's. It reads
        by spelling, so a road by any other spelling is not read, among them getattr, __import__, a name bound at run
        time, compile's flag by value, and another module's function that parses (ast.literal_eval, which the module
        calls). The reader is held to every spelling _TREE_BUILDERS holds, in code: the samples below find one road
        each, a call split across lines among them, and together every spelling of _TREE_BUILDERS, so a spelling added
        there without a sample reds here; and to none in a
        string, a comment or an import of ast by its own name."""
        found = _tree_builder_spellings(_source(os.path.join(HERE, TREE_SKIP[0])))
        inside = {}
        for helper, spelling in ((_parse_text, "ast . parse"), (_bindings_of, "Bindings . of")):
            lines, start = inspect.getsourcelines(helper)
            inside[spelling] = range(start, start + len(lines))
        own = {}
        for name in _OWN_TREE_ROADS:
            lines, start = inspect.getsourcelines(_def_named(name))
            own[name] = range(start, start + len(lines))

        def owners(line):
            return [name for name, span in own.items() if line in span]
        outside = [(line, spelling) for line, spelling in found if line not in inside.get(spelling, ()) and not owners(line)]
        self.assertEqual(outside, [], "roads to a tree or a Bindings outside _parse_text, _bindings_of and the defs of "
                         "_OWN_TREE_ROADS (line, spelling)")
        self.assertEqual(sorted({name for line, _ in found for name in owners(line)}), sorted(_OWN_TREE_ROADS),
                         "_OWN_TREE_ROADS is the defs outside the two helpers that spell a road, and no other")
        self.assertEqual(sorted(spelling for line, spelling in found if not owners(line)), ["Bindings . of", "ast . parse"],
                         "each helper spells its road once")
        samples = ('t = ast.parse(src)\n', 't = ast.parse(\n    src)\n', 'c = compile(src, "m", "exec", ast.PyCF_ONLY_AST)\n',
                   'from ast import parse\n', 'import ast as a\n', 'b = ast_bindings.Bindings.of(t)\n',
                   'b = ast_bindings.Bindings(t)\n')
        for code in samples:
            self.assertEqual(len(_tree_builder_spellings(code)), 1, "the reader finds the road in %r" % code)
        self.assertEqual(sorted({spelling for code in samples for _, spelling in _tree_builder_spellings(code)}),
                         sorted(" ".join(spelling) for spelling in _TREE_BUILDERS), "the samples find every spelling "
                         "_TREE_BUILDERS holds, each spelling joined by spaces as the reader reports it")
        self.assertEqual(_tree_builder_spellings('s = "ast.parse(src)"\n# ast.parse(src)\nimport ast\nimport ast_bindings\n'),
                         [], "the reader finds no road in a string, a comment or an import of ast by its own name")

    def test_the_read_drops_no_cycle_so_each_module_is_freed_by_reference_counting(self):
        """Each module's scan holds its bindings, which are cyclic (a scope holds its declarations and each declaration
        its scope) and hold the module's tree (Bindings.tree, and the nodes the declarations read), so bindings dropped
        unreleased would leave each module's tree to the collector, and the read, which drops each file's tree before it
        parses the next, would hold every tree the collector had not yet reached rather than one. _roads_row releases
        them (ast_bindings' Bindings.release) before it returns, keeping tuples, strings and numbers in the row. Pinned
        by mechanism, the way the thread-stop census pins its tree: a plant directory holding every PLANT_TABLE row as a
        module, every road and the refusal among them, read by _read_root (the function the real tree's read is, its
        environment-write read included) twice with the collector off (so no automatic collection reclaims a cycle
        before the check reads it): the first read warms what a first use imports or fills, a gc.collect() takes the
        baseline, and after the second read, its value alive, gc.collect() finds no unreachable object (DEBUG_SAVEALL
        for that one collection, so a red names the types found). A mutant that drops the release reds it: the plant's
        bindings graphs, left to the collector, keep each planted tree alive, and most_trees is the first assertion it
        reds. The second read also holds one file's tree at a time with no collection to help it:
        its most_trees, the most file trees alive at any file parse (_parse's count), is one, the tree just built (PR
        #850's tenth review round: the unreachable count sees cyclic garbage alone, and a read that kept every tree
        until it returned stayed green here; that mutant reds this and the release pin's same assertion over the tree's
        read); and its born, the tree nodes and ast_bindings objects it made that were alive when its loop ended, by
        class (gc.get_objects() against the list the read took when it started; the count itself changes no collector
        state), is empty (PR #850's eleventh review round: most_trees reads roots, and a read that kept each file
        tree's statements on a list until it returned stayed green there; that mutant reds this and the release pin's
        born assertion). The collector's state as the test found it, and its debug flags, are put back by cleanups registered
        before the test changes them, so a process that runs with the collector off is left off. Each read parses each
        planted module once (_parse_text), so the two move the
        module's counter by two for each module that holds a planted text: nothing caches a plant's parse."""
        was = gc.isenabled()                                           # the collector's state as the test found it...
        self.addCleanup(gc.enable if was else gc.disable)              # ...put back by a cleanup registered BEFORE the disable
        d = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, d, True)
        texts = collections.Counter()
        for i, (_label, _kind, _site, src) in enumerate(PLANT_TABLE):
            with open(os.path.join(d, "test_row_%03d.py" % i), "w", encoding="utf-8") as f:
                f.write(src + "\n")
            texts[_text_key(src + "\n")] += 1
        before = collections.Counter(_PARSES)
        gc.disable()                                                   # no automatic collection before the check
        warm = _read_root(d)
        self.assertEqual(len(warm.table.roads), len(PLANT_TABLE), "the plant's read reads a module per row")
        self.assertEqual(sorted({road for road, _, _ in warm.table.roads.values()}), ["argv", "binding", "neither", "refused"],
                         "the plant reads every road, the refusal among them")
        del warm
        gc.collect()                                                   # the baseline: nothing unreachable before the read under the pin
        flags = gc.get_debug()
        self.addCleanup(gc.set_debug, flags)                           # BEFORE the flag is set
        start = len(gc.garbage)
        gc.set_debug(gc.DEBUG_SAVEALL)
        read = _read_root(d, count=True)
        unreachable = gc.collect()                                     # with `read` alive: what the read dropped in a cycle
        gc.set_debug(flags)
        kinds = collections.Counter(type(o).__name__ for o in gc.garbage[start:])
        del gc.garbage[start:]
        self.assertTrue(read.table.roads, "the second read read no module")
        self.assertEqual(read.most_trees, 1, "the most file trees alive at any file parse of the plant's read, the collector "
                         "off (_parse's count, reset when the read starts, the tree just built among them): one file's tree "
                         "at a time is one")
        self.assertEqual(read.born, {}, "tree nodes and ast_bindings objects the plant's read made that were alive when its "
                         "loop ended, by class (gc.get_objects() against the list taken when it started): a read that holds "
                         "one file's tree at a time keeps none past its loop")
        self.assertEqual(unreachable, 0, "the read dropped %d objects only the collector could reclaim (%s): a cycle the "
                                         "read made and did not break before returning, which would keep each module's tree "
                                         "alive until a collection reached it" % (unreachable, ", ".join("%s %d" % kv for kv in kinds.most_common(8))))
        self.assertEqual({key: _PARSES[key] - before[key] for key in texts}, {key: 2 * n for key, n in texts.items()},
                         "each read parses every planted module once (_parse_text), so the two reads move the module's "
                         "counter by two for each module that holds a planted text")

    def test_a_scan_of_a_planted_source_leaves_no_cycle_holding_its_tree(self):
        """THE PLANT SCAN PIN (PR #850's twelfth review round: _scan_plant's release had no test that reds without it on
        3.10 or 3.12, where an automatic collection reclaimed the cycles it left before the module end's checks read
        them). A scan's bindings are cyclic and hold its tree (the cycle test's docstring says how), so a scan dropped
        with its bindings unreleased leaves its tree to the collector. Pinned by an event, the call's return, with
        automatic collection off for the whole test (gc.disable(), the collector's state as the test found it put back
        by a cleanup registered before the disable), so such a cycle survives to the check: every PLANT_TABLE row is
        scanned by _scan_plant (a refused row's UnreadableSpawn caught) and then by _regex_scan_comparison handed no
        scan, and each call is read by the records it added (_TREES and _BINDINGS past their lengths before the call,
        the weak references tearDownModule reads): once it has returned and its value is dropped, every tree and
        Bindings it recorded is dead. The records read are the call's own: each call's first tree and first Bindings
        carry the filename it was handed, and some call records more than one Bindings, the others its scans of a -c
        program (the only scans a scan makes), whose records are read as well. The check's premise is held on every run:
        a scan built the same way (_SpawnScan over _parse_text) and dropped with its bindings unreleased leaves its tree
        and its Bindings alive, read through the same records, and releasing those bindings then frees both. The reds
        are mutant runs, one release removed in each: _scan_plant's, _regex_scan_comparison's, and the -c program scans'
        (_program_spawns_kernel's and _program_calls'), each red here on 3.10, 3.12 and 3.14t."""
        was = gc.isenabled()                                           # the collector's state as the test found it...
        self.addCleanup(gc.enable if was else gc.disable)              # ...put back by a cleanup registered first
        gc.disable()                                                   # no automatic collection before any check
        name = "scan-pin-plant.py"

        def alive(t0, b0):
            """(kind, filename) of every tree and Bindings recorded past `t0` and `b0` that is still alive."""
            return ([("tree", f) for f, ref in _TREES[t0:] if ref() is not None]
                    + [("bindings", f) for f, ref in _BINDINGS[b0:] if ref() is not None])

        left, not_own, nested = {}, {}, []
        for label, _kind, _site, src in PLANT_TABLE:
            for road in ("_scan_plant", "_regex_scan_comparison"):
                t0, b0 = len(_TREES), len(_BINDINGS)
                try:
                    if road == "_scan_plant":
                        value = _scan_plant(src, name)
                    else:
                        value = _regex_scan_comparison(src, name, scan_all=True)
                except UnreadableSpawn:
                    value = None
                del value                                              # the call has returned: its value dropped too
                row = "%s %s" % (label.split()[0], road)
                first = ([f for f, _ in _TREES[t0:t0 + 1]], [f for f, _ in _BINDINGS[b0:b0 + 1]])
                if first != ([name], [name]):
                    not_own[row] = first
                if len(_BINDINGS) - b0 > 1:
                    nested.append(row)
                if alive(t0, b0):
                    left[row] = alive(t0, b0)
        self.assertEqual(not_own, {}, "calls whose first recorded tree and Bindings are not the plant's (the "
                         "filename the call was handed): (row road: ([the first tree's filename], [the first Bindings' "
                         "filename]))")
        self.assertTrue(nested, "no call recorded more than one Bindings (its scan of a -c program), so no such scan's "
                         "release was read")
        self.assertEqual(sorted(left), [], "calls of a scan of a planted source (row road) that recorded a tree "
                         "or a Bindings still alive once the call had returned, with no collection since the test "
                         "began, %d of them; the first three, with what each left alive (kind, filename): %r. A scan "
                         "dropped with its bindings unreleased leaves its tree in a cycle only the collector reclaims"
                         % (len(left), sorted(left.items())[:3]))
        t0, b0 = len(_TREES), len(_BINDINGS)
        scan = _SpawnScan(_parse_text(PLANT_TABLE[0][3], "scan-pin-unreleased.py"), "scan-pin-unreleased.py")
        scan.sites()
        del scan                                                       # dropped with its bindings unreleased
        self.assertEqual(alive(t0, b0), [("tree", "scan-pin-unreleased.py"), ("bindings", "scan-pin-unreleased.py")],
                         "a scan dropped with its bindings unreleased leaves its tree and its Bindings alive with no "
                         "collection, read through the records the check reads")
        bindings = _BINDINGS[b0][1]()
        bindings.release()
        del bindings
        self.assertEqual(alive(t0, b0), [], "releasing the unreleased scan's bindings frees its tree and its "
                         "Bindings with no collection")

    def test_the_module_that_loads_the_kernel_in_process_and_attaches_places_each_leg_of_the_trio_where_it_is_read(self):
        """Read by position from the module's ast, not by text (_placement_faults): no leg of the trio is written at
        module level; the setUp of every class that attaches or detaches (its own or through super()) sets all three,
        patches the kernel's BUS_PORT, the import-time read, and stubs its _ensure_postal_bus, the revive road, and
        registers cleanups that put all five back. A
        module-level peers assignment is the leak of 2026-09-18 (the header); a module-level port or client-only
        assignment is the leak of 2026-09-22 (fork PR #813's CI: a real bus from another module's test with this module's
        port and client-only); a tearDown-only restore is the hole of review round 1 (a subclass setUp that raises skips
        it). The tunnels module is parsed here, once per run of this test (_PLACEMENT_PARSES, under the key of the text
        it parsed, which the parse check adds to that text's expected count beside the tree's read), and nothing keeps
        the tree past the test (the release pin)."""
        text = _tunnels_source()
        _PLACEMENT_PARSES[_text_key(text)] += 1
        self.assertEqual(_placement_faults(_parse_text(text, "test_kernel_tunnels.py")), [])

    def test_the_placement_check_reds_on_a_planted_module_level_write_and_on_a_teardown_only_restore(self):
        """The check is run over synthetic copies of the real module so it is known to be able to fail (review round 1,
        2026-09-18): a module-level write of ROMP_POSTAL_PEERS restored before the load, in every shape a write takes
        (review round 2 widened the scan from the subscript and setdefault to update, |=, a name bound to os.environ and
        putenv: the subscript alone left a module-level update invisible), each copy faulting exactly once, for the
        write and nothing else; the port and client-only put back at module level where they were until 2026-09-22,
        each faulting once; the dunder and bytes spellings the second verification found passing silently (the third
        commit of 2026-09-22), each faulting once; an augmented write and the key bound as a for, comprehension or with
        target (round 2 of fork PR #894, silent at the round-1 head), each faulting once; a planted update whose keys the
        scan cannot read is loud, naming the line, never a clean pass; and the restore moved back into a tearDown with no cleanup registered, which faults
        every leg and the BUS_PORT and _ensure_postal_bus restores of both attaching classes (the road joined BUS_PORT
        on the reviewer's ruling of round 1 on fork PR #894); and the road's stub deleted from the setUp, and its restore
        dropped from the cleanup, each faulting once per attaching class for that half and nothing else."""
        src = _tunnels_source()
        plants = (
            ("the port, as it was written until 2026-09-22", 'import socket as _socket\n_s = _socket.socket(); _s.bind(("127.0.0.1", 0)); os.environ["ROMP_POSTAL_PORT"] = str(_s.getsockname()[1]); _s.close()\n'),
            ("client-only, as it was written until 2026-09-22", 'os.environ["ROMP_POSTAL_CLIENT_ONLY"] = "1"\n'),
            ("bare", 'os.environ["ROMP_POSTAL_PEERS"] = "0"\n'),
            ("in an if body", 'if True:\n    os.environ["ROMP_POSTAL_PEERS"] = "0"\n'),
            ("by setdefault", 'os.environ.setdefault("ROMP_POSTAL_PEERS", "0")\n'),
            ("by update of a dict literal", 'os.environ.update({"ROMP_POSTAL_PEERS": "0"})\n'),
            ("by update with a keyword", 'os.environ.update(ROMP_POSTAL_PEERS="0")\n'),
            ("by update of a module-level name bound to a dict literal", 'PEERS_OFF = {"ROMP_POSTAL_PEERS": "0"}\nos.environ.update(PEERS_OFF)\n'),
            ("by update of a dict() of keywords", 'os.environ.update(dict(ROMP_POSTAL_PEERS="0"))\n'),
            ("by |=", 'os.environ |= {"ROMP_POSTAL_PEERS": "0"}\n'),
            ("through from os import environ", 'from os import environ as _environ\n_environ["ROMP_POSTAL_PEERS"] = "0"\n'),
            ("through a name bound to os.environ", '_env = os.environ\n_env["ROMP_POSTAL_PEERS"] = "0"\n'),
            ("through a name bound to os.environ, by update", '_env = os.environ\n_env.update(ROMP_POSTAL_PEERS="0")\n'),
            ("by os.putenv", 'os.putenv("ROMP_POSTAL_PEERS", "0")\n'),
            # the fixup of 2026-09-22: everything that executes at import is module level
            ("in a class body", 'class _Planted:\n    os.environ["ROMP_POSTAL_PEERS"] = "0"\n'),
            ("in a block inside a class body", 'class _Planted:\n    if True:\n        os.environ["ROMP_POSTAL_PEERS"] = "0"\n'),
            ("in an if test", 'if os.environ.setdefault("ROMP_POSTAL_PEERS", "0"):\n    pass\n'),
            ("in a default argument value", 'def _planted_default(x=os.environ.setdefault("ROMP_POSTAL_PEERS", "0")):\n    pass\n'),
            ("through a module-local def called at import", 'def _planted_floor():\n    os.environ["ROMP_POSTAL_PEERS"] = "0"\n_planted_floor()\n'),
            ("through a bare decorator", 'def _planted_arm(fn):\n    os.environ["ROMP_POSTAL_PEERS"] = "0"\n    return fn\n@_planted_arm\ndef _planted_decorated():\n    pass\n'),
            ("through an instantiation", 'class _PlantedSeam:\n    def __init__(self):\n        os.environ["ROMP_POSTAL_PEERS"] = "0"\n_PlantedSeam()\n'),
            # the third commit of 2026-09-22: the three shapes that passed silently, read now
            ("by __setitem__", 'os.environ.__setitem__("ROMP_POSTAL_PEERS", "0")\n'),
            ("by __setitem__ unbound, the mapping as the first argument", 'dict.__setitem__(os.environ, "ROMP_POSTAL_PEERS", "0")\n'),
            ("through os.environb with a bytes key", 'os.environb[b"ROMP_POSTAL_PEERS"] = b"0"\n'),
            # round 2 of fork PR #894 (the reviewer's ruling of round 1): an augmented write and a key bound as a target
            ("by +=", 'os.environ["ROMP_POSTAL_PEERS"] += ""\n'),
            ("as a for target", 'for os.environ["ROMP_POSTAL_PEERS"] in ["0"]:\n    pass\n'),
            ("as a comprehension target", '[None for os.environ["ROMP_POSTAL_PEERS"] in ["0"]]\n'),
            ("as a with target", 'import contextlib as _contextlib\nwith _contextlib.nullcontext("0") as os.environ["ROMP_POSTAL_PEERS"]:\n    pass\n'),
        )
        for label, lines in plants:
            faults = _placement_faults(_parse_text(_plant(src, lines)))
            self.assertEqual(len(faults), 1, "%s planted write: one fault, for the write, and nothing else: %r" % (label, faults))
            self.assertIn("written at module level", faults[0], label)
        planted_line = src[:src.index(_PLANT_ANCHOR)].count("\n") + 1
        with self.assertRaises(UnreadableEnvWrite) as loud:
            _placement_faults(_parse_text(_plant(src, "os.environ.update(dict(os.environ))\n")))
        self.assertIn("cannot read the keys of this update at line %d" % planted_line, str(loud.exception))
        faults = _placement_faults(_parse_text(_teardown_only_restore(src)))
        self.assertTrue(faults and all("registers no cleanup" in f for f in faults), "tearDown-only restore: %r" % faults)
        for leg in TRIO + ("BUS_PORT", "_ensure_postal_bus"):
            self.assertEqual(sum(1 for f in faults if leg in f), 2, "%s: one fault per attaching class: %r" % (leg, faults))
        self.assertEqual(len(faults), 2 * (len(TRIO) + 2),
                         "the three legs, BUS_PORT and the _ensure_postal_bus road, per attaching class, nothing else: %r" % faults)
        # the revive road's two halves, each planted out of a copy of the real module (the reviewer's ruling of round 1 on
        # fork PR #894): the stub deleted from _PostalTrio.setUp, and the road's restore dropped from _restore_bus
        for label, old, new, want in (
                ("the stub deleted", "        km._ensure_postal_bus = lambda: self.revives.append(port)\n", "",
                 "does not stub the kernel's _ensure_postal_bus"),
                ("the road's restore dropped", "        km._ensure_postal_bus, km.BUS_PORT = ensure, bus_port\n",
                 "        km.BUS_PORT = bus_port\n", "registers no cleanup that restores the kernel's _ensure_postal_bus")):
            self.assertEqual(src.count(old), 1, "%s: the line the copy rewrites is in the module once" % label)
            faults = _placement_faults(ast.parse(src.replace(old, new)))
            self.assertEqual(len(faults), 2, "%s: one fault per attaching class and nothing else: %r" % (label, faults))
            self.assertTrue(all(want in f for f in faults), "%s: %r" % (label, faults))

